// covers: REQ-KG-CTX-01
import { describe, it, expect } from "vitest";
import { join } from "node:path";
import { contextPack, renderPack } from "./agentContext";
import { buildGraph } from "./discover";
import { loadConfig } from "./config";
import type { GitRunner } from "./gitDates";

/**
 * REQ-KG-CTX-01 — the briefing handed to staff BEFORE it edits a file (founding design §5, the gold).
 *
 * Tested against the MULTI-REPO fixture first, deliberately. The prototype this replaces
 * (`mockups/agent-context.mjs`) stripped one project's sibling repo prefixes with a hardcoded regex,
 * so a single-repo test would pass while the coupling survived untouched — the §12.9 gap again,
 * "names no project" standing in for "assumes no project". Multi-repo is where that assumption breaks.
 *
 * Same pinned clock and inert GitRunner as REQ-1's fixture test, so the pack is a pure function of the
 * committed tree and reproduces on a machine with no git.
 */
const FIXTURES = join(__dirname, "..", "fixtures");
const PINNED = "2000-01-01T00:00:00.000Z";
const NO_GIT: GitRunner = async () => null;

async function packForBaseline(fixture: string, path: string, baseline?: string[]) {
  const root = join(FIXTURES, fixture);
  const config = await loadConfig(root);
  const graph = await buildGraph(root, PINNED, config, NO_GIT);
  return contextPack(graph, config, path, baseline);
}

/** A project with a frozen-but-empty baseline: governed, and nothing grandfathered. */
const packFor = (fixture: string, path: string) => packForBaseline(fixture, path, []);

describe("contextPack — a governed path", () => {
  it("names the doc that governs it", async () => {
    const pack = await packFor("one-repo", "src/checkout.ts");
    expect(pack.halt).toBe(false);
    expect(pack.governedBy.map((d) => d.id)).toContain("main:checkout-spec");
  });

  it("lists the requirements that doc specifies, and what proves each", async () => {
    const pack = await packFor("one-repo", "src/checkout.ts");
    const ids = pack.requirements.map((r) => r.id);
    expect(ids.length).toBeGreaterThan(0);
    // REQ-FX-3 is covered by src/checkout.test.ts in the fixture's feature registry.
    const proven = pack.requirements.find((r) => r.provenBy.length > 0);
    expect(proven, "at least one requirement must show its proving test").toBeTruthy();
  });

  // The gap is the whole point of the briefing: a requirement with no covering test means there is no
  // safety net under the edit about to happen.
  it("flags requirements with no covering test", async () => {
    const pack = await packFor("one-repo", "src/checkout.ts");
    expect(pack.requirements.some((r) => r.provenBy.length === 0)).toBe(true);
  });
});

/**
 * A test file that PROVES a requirement is not ungoverned — the requirement is precisely the statement
 * of what it must assert. The gate used to halt on one anyway, because governance was read only from a
 * doc's `governs:` list and no doc lists test files.
 *
 * Found by writing `isMain.test.ts`: it is cited in REQ-KG-SUB-06's own `covers:`, and the briefing
 * still said nothing governs it. That halts an agent out of the one file it must edit to close a gap
 * the gate is complaining about — so the gate blocked its own remedy.
 */
describe("contextPack — a test is governed by what it proves", () => {
  const graph: any = {
    generatedAt: "",
    nodes: [
      { id: "main:spec", type: "doc", title: "Spec", path: ".github/system-design/S.md", status: "current" },
      { id: "REQ-S-1", type: "requirement", title: "A total sums its lines.", text: "A total sums its lines." },
      { id: "main:src/total.test.ts", type: "test", kind: "unit-fe", title: "total.test.ts", path: "src/total.test.ts" },
      { id: "main:src/stray.test.ts", type: "test", kind: "unit-fe", title: "stray.test.ts", path: "src/stray.test.ts" },
    ],
    edges: [
      { from: "main:spec", to: "REQ-S-1", type: "specifies" },
      { from: "main:src/total.test.ts", to: "REQ-S-1", type: "covers" },
    ],
    issues: [],
  };
  const config: any = { repos: [{ name: "main", subdir: "" }] };

  it("does not halt on a test that covers a requirement", () => {
    const pack = contextPack(graph, config, "src/total.test.ts", []);
    expect(pack.halt).toBe(false);
    expect(pack.requirements.map((r) => r.id)).toContain("REQ-S-1");
  });

  it("names the doc behind the requirement as the owner", () => {
    const pack = contextPack(graph, config, "src/total.test.ts", []);
    expect(pack.governedBy.map((d) => d.id)).toContain("main:spec");
  });

  // The exemption must come from the covers edge, not from being a test. A test proving nothing is
  // exactly the bare, unanchored test the gate exists to catch.
  it("still halts on a test that proves nothing", () => {
    expect(contextPack(graph, config, "src/stray.test.ts", []).halt).toBe(true);
  });
});

/**
 * Generated requirements are a MIRROR of the code, so they cannot contradict it — if the code is
 * wrong, a drafted requirement documents the bug as intent. That is tolerable while it is visibly
 * unapproved and fatal the moment it reads like a decision the CEO made, so the briefing has to tell
 * the two apart. Without this, `kg-draft-spec` would quietly launder generated prose into canon.
 */
describe("contextPack — a drafted requirement is not an approved one", () => {
  const graph: any = {
    generatedAt: "",
    nodes: [
      { id: "main:drafted", type: "doc", title: "Checkout (drafted)", path: ".github/system-design/D.md", status: "draft" },
      { id: "main:approved", type: "doc", title: "Pricing", path: ".github/system-design/A.md", status: "current" },
      { id: "REQ-D-1", type: "requirement", title: "Totals sum line items.", text: "Totals sum line items." },
      { id: "REQ-A-1", type: "requirement", title: "A voucher never goes below zero.", text: "A voucher never goes below zero." },
    ],
    edges: [
      { from: "main:drafted", to: "src/pay.ts", type: "governs" },
      { from: "main:approved", to: "src/pay.ts", type: "governs" },
      { from: "main:drafted", to: "REQ-D-1", type: "specifies" },
      { from: "main:approved", to: "REQ-A-1", type: "specifies" },
    ],
    issues: [],
  };
  const config: any = { repos: [{ name: "main", subdir: "" }] };

  it("marks a requirement whose owning doc is still a draft", () => {
    const pack = contextPack(graph, config, "src/pay.ts", []);
    expect(pack.requirements.find((r) => r.id === "REQ-D-1")?.draft).toBe(true);
    expect(pack.requirements.find((r) => r.id === "REQ-A-1")?.draft).toBe(false);
  });

  it("says so in the briefing, in words that stop someone treating it as decided", () => {
    const text = renderPack(contextPack(graph, config, "src/pay.ts", []));
    expect(text).toMatch(/UNAPPROVED DRAFT/);
    // The warning must attach to the drafted requirement, not float loose at the bottom.
    const line = text.split("\n").find((l) => l.includes("REQ-D-1"))!;
    expect(line).toMatch(/UNAPPROVED DRAFT/);
    expect(text.split("\n").find((l) => l.includes("REQ-A-1"))).not.toMatch(/UNAPPROVED DRAFT/);
  });
});

describe("contextPack — multi-repo, where a hardcoded prefix would break", () => {
  // These two replace a pair that asserted `Array.isArray(...)` and `toBeTruthy()` — both of which
  // passed just as happily when the pack came back completely empty, so they proved nothing about
  // the multi-repo resolution they were named for. Rule 5 cuts the other way here: strengthening a
  // test that could not fail is not weakening it.
  //
  // The multi-repo fixture declares no `governs:` anywhere, so ownership comes from a FEATURE whose
  // path glob is workspace-relative and reaches into a nested sibling repo. That crossing is the
  // multi-repo resolution.
  it("lets a feature's glob claim a path inside a nested sibling repo", async () => {
    const pack = await packFor("multi-repo", "svc_backend/tests/test_rates.py");
    expect(pack.features.map((f) => f.id).some((id) => id.endsWith(":rates-api"))).toBe(true);
    expect(pack.halt).toBe(false);
  });

  it("does not let one sibling's glob claim another sibling's path", async () => {
    const pack = await packFor("multi-repo", "svc_frontend/src/rates/widget.test.ts");
    // rates-widget covers svc_frontend/src/rates/**; rates-api covers svc_backend/tests/** only.
    const ids = pack.features.map((f) => f.id);
    expect(ids.some((id) => id.endsWith(":rates-widget"))).toBe(true);
    expect(ids.some((id) => id.endsWith(":rates-api"))).toBe(false);
  });

  it("halts on a nested-repo path that nothing claims", async () => {
    const pack = await packFor("multi-repo", "svc_backend/app/unclaimed.py");
    expect(pack.halt).toBe(true);
  });
});

describe("contextPack — an ungoverned path HALTS", () => {
  it("halts rather than warning, so the briefing cannot be scrolled past", async () => {
    const pack = await packFor("one-repo", "src/totallyNewThing.ts");
    expect(pack.halt).toBe(true);
    expect(pack.governedBy).toEqual([]);
    expect(pack.reason).toMatch(/requirement/i);
  });

  // A warning that does not stop anything is the `|| echo` failure: the signal exists and nobody
  // looks. §9c — the gate blocks; report-only is decoration.
  it("does not halt merely because a governed path has gaps", async () => {
    const pack = await packFor("one-repo", "src/checkout.ts");
    expect(pack.halt).toBe(false);
  });
});

/**
 * The frozen baseline (§10.3) — "existing untouched code stays legal; new ungoverned code fails".
 *
 * Without this the pack halts on EVERY file of any project that has not been governed yet, which is
 * every project on the day it installs the plugin. Halting a user out of their own repo on install
 * is not a strict gate, it is a broken product — and the ratchet idiom for exactly this was already
 * a locked decision.
 */
describe("contextPack — the frozen baseline", () => {
  const pack = (path: string, baseline?: string[]) =>
    packForBaseline("one-repo", path, baseline);

  it("never halts when the project has NO baseline — it is not governed yet", async () => {
    const p = await pack("src/totallyNewThing.ts", undefined);
    expect(p.halt).toBe(false);
    expect(p.grandfathered).toBe(true);
  });

  it("does not halt on ungoverned code the baseline already froze", async () => {
    const p = await pack("src/legacyThing.ts", ["src/legacyThing.ts"]);
    expect(p.halt).toBe(false);
    expect(p.grandfathered).toBe(true);
  });

  it("HALTS on ungoverned code the baseline does not know — this is new", async () => {
    const p = await pack("src/brandNew.ts", ["src/legacyThing.ts"]);
    expect(p.halt).toBe(true);
    expect(p.grandfathered).toBe(false);
  });

  it("never grandfathers a governed path — governance is not a concession", async () => {
    const p = await pack("src/checkout.ts", []);
    expect(p.halt).toBe(false);
    expect(p.grandfathered).toBe(false);
  });
});

describe("renderPack — the text staff actually reads", () => {
  it("leads with STOP and nothing else when the path is ungoverned", async () => {
    const text = renderPack(await packFor("one-repo", "src/totallyNewThing.ts"));
    expect(text).toContain("STOP");
    // The briefing must not also print a requirements section: a halt that still renders a normal
    // pack invites skimming past it, which is the `|| echo` failure in presentation form.
    expect(text).not.toContain("## Requirements");
  });

  it("names the requirement and what proves it, and flags what proves nothing", async () => {
    const text = renderPack(await packFor("one-repo", "src/checkout.ts"));
    expect(text).toContain("## Governed by");
    expect(text).toContain("NO COVERING TEST");
  });
});

// covers: REQ-KG-EVID-03, REQ-KG-EVID-04, REQ-KG-05
import { describe, it, expect } from "vitest";
import { applyEvidence } from "./applyEvidence";

const graph = {
  generatedAt: "T",
  nodes: [
    { id: "frontend:add-3", type: "test", kind: "e2e", title: "Add 3" },
    { id: "frontend:bil-1", type: "test", kind: "e2e", title: "BIL-1" },
    { id: "frontend:some-unit.test.ts", type: "test", kind: "unit-fe", title: "some-unit.test.ts" },
    { id: "backend:x", type: "doc", title: "X" },
  ],
  edges: [], issues: [],
} as any;

const index = JSON.stringify({
  branch: "e2e-evidence",
  updatedAt: "2026-07-05T00:00:00Z",
  cases: {
    "add-3": {
      sha: "abc1234",
      shots: {
        "add3-1-rent-roll.png": "https://raw.githubusercontent.com/acme-org/svc_frontend/e2e-evidence/kg-cases/add-3/abc1234/01-add3-1-rent-roll.png",
      },
    },
  },
});

describe("applyEvidence", () => {
  it("attaches an evidence map onto the matching e2e test node (bare-id match)", () => {
    const g = applyEvidence(graph, index);
    const n = g.nodes.find((n: any) => n.id === "frontend:add-3");
    expect(n.evidence).toEqual({
      "add3-1-rent-roll.png": "https://raw.githubusercontent.com/acme-org/svc_frontend/e2e-evidence/kg-cases/add-3/abc1234/01-add3-1-rent-roll.png",
    });
  });

  it("leaves e2e nodes with no matching case entry untouched", () => {
    const g = applyEvidence(graph, index);
    expect(g.nodes.find((n: any) => n.id === "frontend:bil-1").evidence).toBeUndefined();
  });

  it("never attaches evidence to a non-e2e test node even if the bare id matched", () => {
    const withUnitMatch = JSON.parse(index);
    withUnitMatch.cases["some-unit.test.ts"] = { sha: "z", shots: { "x.png": "https://example.com/x.png" } };
    const g = applyEvidence(graph, JSON.stringify(withUnitMatch));
    expect(g.nodes.find((n: any) => n.id === "frontend:some-unit.test.ts").evidence).toBeUndefined();
  });

  it("is case-insensitive on the bare case id, matching the rest of the graph's bare-id convention", () => {
    const upper = JSON.parse(index);
    upper.cases["ADD-3"] = upper.cases["add-3"];
    delete upper.cases["add-3"];
    const g = applyEvidence(graph, JSON.stringify(upper));
    expect(g.nodes.find((n: any) => n.id === "frontend:add-3").evidence).toBeDefined();
  });

  it("returns the graph unchanged when there is no evidence index file", () => {
    const g = applyEvidence(graph, null);
    expect(g.nodes.find((n: any) => n.id === "frontend:add-3").evidence).toBeUndefined();
  });

  it("does not throw on a malformed/empty index and leaves the graph unchanged", () => {
    expect(applyEvidence(graph, "not json").nodes).toEqual(graph.nodes);
    expect(applyEvidence(graph, "{}").nodes).toEqual(graph.nodes);
  });

  it("is deterministic: same file content in, same graph out (freshness-check safe)", () => {
    const a = applyEvidence(graph, index);
    const b = applyEvidence(graph, index);
    expect(JSON.stringify(a)).toBe(JSON.stringify(b));
  });
});

/**
 * REQ-KG-05's NEGATIVE clause — screenshot binaries never enter the committed graph.
 *
 * This was the one requirement left uncovered by the 2026-07-24 backfill, and deliberately so: the
 * upload path proved the positive half thoroughly while nothing asserted the negative, and a
 * `covers:` edge over an unproven clause is the exact failure §10.2 records. Enforcing it is what
 * closes the gap — a test alone would only have described the hole.
 *
 * The graph is a pure function of the tree and is committed on every build. An inline `data:` image
 * would put megabytes of base64 into `knowledge-graph.json`, and — worse than size — it would put
 * the *content* of a screenshot into version control, which is precisely what storing evidence out
 * of band exists to prevent.
 */
describe("evidence carries references, never binaries (REQ-KG-05)", () => {
  const g = { generatedAt: "T", nodes: [{ id: "main:checkout", type: "test", kind: "e2e" }], edges: [], issues: [] } as any;
  const idx = (shots: Record<string, string>) =>
    JSON.stringify({ branch: "b", updatedAt: "T", cases: { checkout: { sha: "abc", shots } } });

  it("keeps ordinary URL references", () => {
    const out = applyEvidence(g, idx({ "01-start.png": "https://blobs.example.com/kg/checkout/01-start.png" }));
    expect(out.nodes[0].evidence).toEqual({ "01-start.png": "https://blobs.example.com/kg/checkout/01-start.png" });
  });

  it("drops an inline data: image so it can never reach knowledge-graph.json", () => {
    const out = applyEvidence(g, idx({ "01-start.png": "data:image/png;base64,iVBORw0KGgoAAAANSUhEUg==" }));
    expect(out.nodes[0].evidence).toBeUndefined();
    expect(JSON.stringify(out)).not.toContain("base64");
  });

  it("keeps the good references and drops only the binary one", () => {
    const out = applyEvidence(
      g,
      idx({ "01.png": "https://blobs.example.com/a.png", "02.png": "data:image/png;base64,AAAA" }),
    );
    expect(out.nodes[0].evidence).toEqual({ "01.png": "https://blobs.example.com/a.png" });
  });
});

import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, it, expect } from "vitest";
import { report, writeArtifacts } from "./artifacts";
import { healthForGraph } from "./summarize";
const g = { generatedAt: "T", nodes: [], edges: [], issues: [{ kind: "orphan-doc", node: "backend:x", detail: "d" }] } as any;
describe("report", () => {
  it("keeps the existing summary shape", () => {
    expect(report(g)).toContain("**Issues:** 1");
  });
  it("appends a Since-last-sync section when delta lines are given", () => {
    const r = report(g, ["+1 requirement (backend:req-x)"]);
    expect(r).toContain("## Since last sync");
    expect(r).toContain("+1 requirement");
  });
  it("adds a Results timestamp line after Generated when lastRun exists", () => {
    const withRun = { ...g, lastRun: { at: "2026-07-03T00:00:00Z", commit: "abc1234" } };
    const r = report(withRun);
    expect(r).toContain("Generated: T\n\nResults: 2026-07-03T00:00:00Z (abc1234)\n");
  });
  it("shows 'Results: none recorded' when lastRun is absent", () => {
    const r = report(g);
    expect(r).toContain("Generated: T\n\nResults: none recorded\n");
  });
});

describe("writeArtifacts", () => {
  // A project adopting the tool has no artifact dir yet — it is the project's data, not something
  // the tool ships (§10.9, TOOL_DIR). Until phase 3 this threw ENOENT on the very first build,
  // because the dir had only ever existed by virtue of the tool living inside it. Self-hosting
  // found it: `npm run build` on this repo crashed writing knowledge-graph.json.
  it("creates the output directory when the project has none yet", async () => {
    const tmp = await mkdtemp(join(tmpdir(), "kg-artifacts-"));
    const outDir = join(tmp, "knowledge-graph");
    try {
      const base = { generatedAt: "T", nodes: [], edges: [], issues: [] } as any;
      // health is attached by the build, not by the parsers — mirror that rather than invent a shape.
      const empty = { ...base, health: healthForGraph(base) };
      await writeArtifacts(empty, outDir);
      const written = JSON.parse(await readFile(join(outDir, "knowledge-graph.json"), "utf8"));
      expect(written.nodes).toEqual([]);
    } finally {
      await rm(tmp, { recursive: true, force: true });
    }
  });
});

// covers: REQ-KG-05, REQ-KG-SERVE-02
import { describe, it, expect } from "vitest";
import {
  objectKey, objectUrl, uploadArgs, listArgs, pruneArgs, presignArgs, parseShaDirs,
  keyOf, evidenceRef, evidenceKeyFromPath, blobAdapter, EVIDENCE_ROUTE, PRESIGN_TTL_SECONDS,
} from "./blobStore";
import { runUpload, blobRef, type ShotDirEntry, type FsLike } from "./shotsUpload";
import type { Evidence } from "./config";

/**
 * The S3 evidence transport, tested as COMMANDS rather than as uploads — the same idiom as
 * treeKillCommand and buildRunArgs, and for the same reason: the subprocess is the untestable part,
 * the argv is where the bugs live.
 *
 * Credentials never appear here. They resolve at run time from the standard AWS chain, so every
 * command below is safe to assert on verbatim (REQ-KG-05).
 */
const S3: Extract<Evidence, { kind: "blob" }> = { kind: "blob", bucket: "acme-kg", prefix: "kg-cases", region: "us-east-1" };
const ROOT: Extract<Evidence, { kind: "blob" }> = { kind: "blob", bucket: "acme-kg", prefix: "", region: "us-east-1" };

describe("objectKey — mirrors the github branch layout so destinations stay comparable", () => {
  it("composes prefix/case/sha/file", () => {
    expect(objectKey(S3, "checkout", "a1b2c3d", "01-start.png")).toBe("kg-cases/checkout/a1b2c3d/01-start.png");
  });

  it("omits the prefix segment when the bucket root is used", () => {
    expect(objectKey(ROOT, "checkout", "a1b2c3d", "01-start.png")).toBe("checkout/a1b2c3d/01-start.png");
  });

  // Bare ids are lower-cased everywhere in the graph; a key that disagreed would make the viewer's
  // lookup miss silently rather than loudly.
  it("lower-cases the case id, matching the graph's bare-id convention", () => {
    expect(objectKey(S3, "CheckOut", "a1b2c3d", "01.png")).toBe("kg-cases/checkout/a1b2c3d/01.png");
  });
});

describe("objectUrl — durable address, composed from coordinates", () => {
  it("uses the regional virtual-hosted form", () => {
    expect(objectUrl(S3, "kg-cases/checkout/a1/01.png")).toBe(
      "https://acme-kg.s3.us-east-1.amazonaws.com/kg-cases/checkout/a1/01.png",
    );
  });
});

describe("aws argv", () => {
  it("uploads a single object with its region", () => {
    expect(uploadArgs(S3, "/tmp/01.png", "kg-cases/checkout/a1/01.png")).toEqual([
      "s3", "cp", "/tmp/01.png", "s3://acme-kg/kg-cases/checkout/a1/01.png", "--region", "us-east-1",
    ]);
  });

  it("lists a case's shas so pruning and index rebuilding still work", () => {
    expect(listArgs(S3, "checkout")).toEqual([
      "s3", "ls", "s3://acme-kg/kg-cases/checkout/", "--region", "us-east-1",
    ]);
  });

  it("prunes one sha directory recursively", () => {
    expect(pruneArgs(S3, "checkout", "old1234")).toEqual([
      "s3", "rm", "s3://acme-kg/kg-cases/checkout/old1234/", "--recursive", "--region", "us-east-1",
    ]);
  });

  // The bucket stays PRIVATE. A browser <img> cannot send an auth header, so serve.ts mints a
  // short-lived signed GET on demand. Expiry is a feature here, not the flaw it was for upload:
  // the URL is generated per view and never committed.
  it("presigns a read with a short ttl", () => {
    expect(presignArgs(S3, "kg-cases/checkout/a1/01.png")).toEqual([
      "s3", "presign", "s3://acme-kg/kg-cases/checkout/a1/01.png",
      "--expires-in", String(PRESIGN_TTL_SECONDS), "--region", "us-east-1",
    ]);
  });

  it("keeps the presign ttl short enough that a leaked url dies quickly", () => {
    expect(PRESIGN_TTL_SECONDS).toBeLessThanOrEqual(900);
  });
});

describe("parseShaDirs — reads sha dirs out of `aws s3 ls` output", () => {
  it("takes the PRE entries and drops their trailing slash", () => {
    const out = ["                           PRE a1b2c3d/", "                           PRE 9f8e7d6/"].join("\n");
    expect(parseShaDirs(out)).toEqual(["a1b2c3d", "9f8e7d6"]);
  });

  it("ignores object lines, which are files rather than sha dirs", () => {
    const out = ["2026-07-24 12:00:00       1234 stray.png", "                           PRE a1b2c3d/"].join("\n");
    expect(parseShaDirs(out)).toEqual(["a1b2c3d"]);
  });

  it("returns nothing for an empty listing (a case never uploaded before)", () => {
    expect(parseShaDirs("")).toEqual([]);
    expect(parseShaDirs("\n  \n")).toEqual([]);
  });
});

describe("keyOf — the seam between runUpload's remote path and an object key", () => {
  // `runUpload` composes `kg-cases/<case>/<sha>/<file>` — the GitHub branch's layout, and the ONLY
  // shape either adapter is handed. S3 roots the same tree at the CONFIGURED prefix instead, so the
  // whole mapping is: drop the branch root, prepend the prefix. Asserted against `objectKey` rather
  // than a literal, because the thing that must hold is that the two agree — a key composed one way
  // that disagreed with the other would upload to a path the index never points at.
  it("agrees with objectKey for the same case/sha/file", () => {
    expect(keyOf(S3, "kg-cases/checkout/a1b2c3d/01-start.png")).toBe(
      objectKey(S3, "checkout", "a1b2c3d", "01-start.png"),
    );
  });

  it("drops the segment entirely at the bucket root", () => {
    expect(keyOf(ROOT, "kg-cases/checkout/a1b2c3d/01-start.png")).toBe("checkout/a1b2c3d/01-start.png");
  });
});

describe("evidenceRef / evidenceKeyFromPath — what the committed index stores, and how it is read back", () => {
  // The index stores the KEY behind serve.ts's route, never a URL: a pre-signed URL would expire
  // long before the committed index does, and the bucket is private so the durable objectUrl cannot
  // load in an <img>. One constant owns both ends, so the writer and the reader cannot drift.
  it("addresses a shot through the serve route, carrying the key verbatim", () => {
    expect(evidenceRef("kg-cases/checkout/a1/01.png")).toBe("/evidence/kg-cases/checkout/a1/01.png");
    expect(evidenceRef("x.png").startsWith(EVIDENCE_ROUTE)).toBe(true);
  });

  it("round-trips a key written by the uploader back out of a request path", () => {
    const key = objectKey(S3, "CheckOut", "a1b2c3d", "01-start.png");
    expect(evidenceKeyFromPath(S3, evidenceRef(key))).toBe(key);
  });

  // REQ-KG-SERVE-02's confinement, in key space rather than path space: a request can only ever
  // name an object under the CONFIGURED prefix, so the route can never be used as a generic signer
  // for the rest of someone's bucket.
  it("refuses a key outside the configured prefix, including a sibling that merely shares its name", () => {
    expect(evidenceKeyFromPath(S3, "/evidence/other/checkout/a1/01.png")).toBeNull();
    expect(evidenceKeyFromPath(S3, "/evidence/kg-cases-evil/checkout/a1/01.png")).toBeNull();
  });

  it("refuses traversal, raw and URL-encoded", () => {
    for (const p of [
      "/evidence/kg-cases/../../secrets/01.png",
      "/evidence/kg-cases/%2e%2e/%2e%2e/secrets/01.png",
      "/evidence/kg-cases/checkout/..%2Fa1/01.png",
    ]) expect(evidenceKeyFromPath(S3, p), p).toBeNull();
  });

  it("refuses backslashes, drive letters, dotfiles, empty segments and malformed percent-encoding", () => {
    for (const p of [
      "/evidence/kg-cases\\checkout\\a1\\01.png",
      "/evidence/kg-cases/C:/a1/01.png",
      "/evidence/kg-cases/.env/01.png",
      "/evidence/kg-cases//a1/01.png",
      "/evidence/kg-cases/checkout/%zz.png",
      "/evidence/",
      "/shots/kg-cases/checkout/a1/01.png",
    ]) expect(evidenceKeyFromPath(S3, p), p).toBeNull();
  });

  it("refuses a non-image object — evidence is screenshots, and nothing else needs signing", () => {
    expect(evidenceKeyFromPath(S3, "/evidence/kg-cases/checkout/a1/creds.json")).toBeNull();
    expect(evidenceKeyFromPath(S3, "/evidence/kg-cases/checkout/a1/shot.jpeg")).toBe("kg-cases/checkout/a1/shot.jpeg");
  });

  it("treats the bucket root as the root when no prefix is configured", () => {
    expect(evidenceKeyFromPath(ROOT, "/evidence/checkout/a1/01.png")).toBe("checkout/a1/01.png");
    expect(evidenceKeyFromPath(ROOT, "/evidence/../01.png")).toBeNull();
  });
});

/**
 * The adapter — the only part of the S3 transport that touches a subprocess, tested through an
 * injected runner so the argv stays asserted verbatim and no test ever shells out to `aws`.
 *
 * All three assertions below are traps found by READING `shotsUpload.ts`'s github adapter rather
 * than by guessing at the aws equivalent; each one fails in a way that looks like success.
 */
describe("blobAdapter", () => {
  const spy = () => {
    const calls: string[][] = [];
    const wrote: Buffer[] = [];
    const warnings: string[] = [];
    return { calls, wrote, warnings };
  };
  const deps = (s: ReturnType<typeof spy>, aws?: (args: string[]) => Promise<string>) => ({
    aws: aws ?? (async (args: string[]) => { s.calls.push(args); return ""; }),
    withRawTempFile: async <T>(bytes: Buffer, fn: (path: string) => Promise<T>): Promise<T> => {
      s.wrote.push(bytes);
      return fn(`/tmp/kg-blob-${s.wrote.length}.png`);
    },
    warn: (m: string) => { s.warnings.push(m); },
  });

  // TRAP 1. `withTempBodyFile` in shotsUpload.ts is a `gh api --input` JSON body writer, NOT a
  // raw-bytes writer. Reusing it here would upload the JSON wrapper in place of the PNG — and the
  // upload would still exit 0, so the bucket would fill with plausible-looking garbage.
  it("hands the PNG bytes themselves to the temp file, and uploads that exact file", async () => {
    const s = spy();
    const png = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a]);
    await blobAdapter(S3, deps(s)).putFile("kg-cases/add-3/abc1234/01-x.png", png);
    expect(s.wrote[0]).toEqual(png);
    expect(s.calls[0]).toEqual(uploadArgs(S3, "/tmp/kg-blob-1.png", "kg-cases/add-3/abc1234/01-x.png"));
  });

  // TRAP 2. putFile/deleteDir are handed a repo-relative remotePath, not a case id — the builders
  // compose from (caseId, sha, filename), which fits listCaseShas and neither of these.
  it("prunes a sha dir addressed as a remote path, under the configured prefix", async () => {
    const s = spy();
    await blobAdapter(S3, deps(s)).deleteDir("kg-cases/add-3/old1234");
    expect(s.calls[0]).toEqual(pruneArgs(S3, "add-3", "old1234"));
  });

  // TRAP 3. `aws s3 ls` EXITS NON-ZERO on a prefix with no objects, which is exactly the state of
  // every case's first upload. A throw here would fail the run before a single file was written.
  it("reports no existing shas when the case has never been uploaded (`aws s3 ls` exits non-zero)", async () => {
    const s = spy();
    const gh = blobAdapter(S3, deps(s, async () => { throw new Error("An error occurred (NoSuchKey)"); }));
    await expect(gh.listCaseShas("brand-new")).resolves.toEqual([]);
  });

  it("lists a case's existing shas from the aws listing", async () => {
    const s = spy();
    const gh = blobAdapter(S3, deps(s, async (args) => {
      s.calls.push(args);
      return "                           PRE a1b2c3d/\n                           PRE 9f8e7d6/\n";
    }));
    expect(await gh.listCaseShas("checkout")).toEqual(["a1b2c3d", "9f8e7d6"]);
    expect(s.calls[0]).toEqual(listArgs(S3, "checkout"));
  });

  // Pruning is best-effort in the github adapter for a reason: evidence that uploaded fine must not
  // be reported as a failed run because an old dir could not be removed.
  it("warns rather than throwing when a prune fails, so a good upload is never failed by it", async () => {
    const s = spy();
    const gh = blobAdapter(S3, deps(s, async () => { throw new Error("AccessDenied"); }));
    await expect(gh.deleteDir("kg-cases/add-3/old1234")).resolves.toBeUndefined();
    expect(s.warnings.join(" ")).toContain("AccessDenied");
  });

  // End to end through the real orchestrator: this is what pins the `kg-cases/…` layout literal in
  // runUpload to keyOf's understanding of it. If either side moved, the uploaded key and the key the
  // index points at would silently disagree.
  it("drives a real runUpload — uploaded key, pruned dir and index reference all agree", async () => {
    const s = spy();
    const fs: FsLike & { readFile: NonNullable<FsLike["readFile"]> } = {
      listDir: async () => [],
      readFile: async () => Buffer.from([0x89, 0x50, 0x4e, 0x47]),
    };
    const local: ShotDirEntry[] = [{ caseId: "ADD-3", dir: "/shots/ADD-3", files: ["add3-1-rent-roll.png"] }];
    const gh = blobAdapter(S3, deps(s, async (args) => {
      s.calls.push(args);
      return args[1] === "ls" ? "                           PRE sha3/\n                           PRE sha2/\n                           PRE sha1/\n" : "";
    }));
    const result = await runUpload({
      ref: blobRef(S3), local, graphCaseIds: new Set(["add-3"]), sha: "shaNEW",
      dryRun: false, fs, gh, now: "2026-07-24T00:00:00.000Z",
    });

    const key = objectKey(S3, "add-3", "shaNEW", "01-add3-1-rent-roll.png");
    expect(s.calls[0]).toEqual(uploadArgs(S3, "/tmp/kg-blob-1.png", key));
    expect(s.calls).toContainEqual(pruneArgs(S3, "add-3", "sha1"));
    expect(s.calls).not.toContainEqual(pruneArgs(S3, "add-3", "sha2"));
    // The committed index points at the key that was actually uploaded — through the route, so the
    // signature can be minted per view rather than frozen into a file.
    expect(result.index.cases["add-3"].shots["add3-1-rent-roll.png"]).toBe(evidenceRef(key));
    expect(evidenceKeyFromPath(S3, result.index.cases["add-3"].shots["add3-1-rent-roll.png"])).toBe(key);
    // Nothing that expires, and no bucket host, reaches the committed file.
    expect(JSON.stringify(result.index)).not.toContain("amazonaws.com");
    expect(result.index.branch).toBeUndefined();
  });
});

