describe("assemble — duplicate-id determinism", () => {
  const dupParts: ParseResult = {
    nodes: [
      { id: "dup", type: "doc", title: "Dup Z", path: "z/dup.md", status: "current" },
      { id: "dup", type: "doc", title: "Dup A", path: "a/dup.md", status: "current" },
