/**
 * broken-proof — a cited proof that names nothing (REQ-KG-CORE-06).
 *
 * `provenBy` is where a doc's `covers:` frontmatter lands, and it was the one authored claim in the
 * graph that could be WRONG WITHOUT CONSEQUENCE: `provenByTest` kept the slugs that resolved to a
 * test node and silently discarded the rest, so a requirement could cite four proofs, have three of
 * them name files that do not exist, and still read as fully proven — with nothing anywhere saying
 * so. Found live: the port moved every test out of `tools/knowledge-graph/src/`, and 48 of the 49
 * cited paths in this repo's own PRD kept pointing at the old location. It survived a coverage
 * backfill and a PRD split precisely because nothing reported it.
 *
 * The asymmetry it fixes: an edge's TARGET has always been validated (`broken-link`, REQ-KG-CORE-01)
 * while a requirement's cited PROOF was not. Note this is a claim about the citation, not about
 * coverage — a requirement genuinely proven by a `covers:` comment still gets flagged for the dead
 * path it also cites, because "proven anyway" is exactly how the wrong citation survives.
 */
describe("assemble — broken-proof", () => {
  const doc = (provenBy: string[]): ParseResult => ({
    nodes: [
      { id: "tool-prd", type: "doc", title: "Tool PRD", status: "current", entrypoint: true },
      { id: "REQ-TOOL-01", type: "requirement", title: "req 1", provenBy },
      { id: "main:src/real.test.ts", type: "test", kind: "unit-fe", title: "real test" },
      { id: "main:src/helper.ts", type: "doc", title: "not a test", status: "current" },
    ],
    edges: [{ from: "tool-prd", to: "REQ-TOOL-01", type: "specifies", source: "doc" }],
  });

  it("flags a provenBy entry that resolves to no node at all", () => {
    const g = assemble(doc(["main:tools/knowledge-graph/src/real.test.ts"]), "T");
    expect(g.issues).toContainEqual({
      kind: "broken-proof",
      node: "REQ-TOOL-01",
      detail: "cited proof 'main:tools/knowledge-graph/src/real.test.ts' is not a test node",
    });
  });

  it("flags a provenBy entry that resolves to a node which is not a test", () => {
    const g = assemble(doc(["main:src/helper.ts"]), "T");
    expect(g.issues.filter((i) => i.kind === "broken-proof")).toHaveLength(1);
  });

  it("accepts a resolving proof, by full id and by bare slug alike", () => {
    for (const slug of ["main:src/real.test.ts", "src/real.test.ts"]) {
      const g = assemble(doc([slug]), "T");
      expect(g.issues.filter((i) => i.kind === "broken-proof"), slug).toHaveLength(0);
    }
  });

  // The point of the whole issue kind: a dead citation must not be masked by a live one.
  it("flags the dead citation even when a sibling citation proves the requirement", () => {
    const g = assemble(doc(["main:src/real.test.ts", "main:tools/knowledge-graph/src/gone.test.ts"]), "T");
    expect(g.issues.filter((i) => i.kind === "uncovered-requirement")).toHaveLength(0);
    expect(g.issues.filter((i) => i.kind === "broken-proof")).toHaveLength(1);
  });

  it("says nothing about a requirement that cites no proof — that is uncovered-requirement's job", () => {
    const g = assemble(doc([]), "T");
    expect(g.issues.filter((i) => i.kind === "broken-proof")).toHaveLength(0);
    expect(g.issues).toContainEqual({ kind: "uncovered-requirement", node: "REQ-TOOL-01", detail: "no test covers this requirement" });
  });
});

// graph.registries — viewer-only payload (features.yaml basename → raw file text) powering the
// in-viewer registry document page. Explicitly NOT nodes/edges: it must never influence
// issues/ratchet, and it must serialize deterministically (keys inserted sorted, since
// JSON.stringify preserves insertion order).
describe("assemble — graph.registries (inline feature-registry yaml)", () => {
  const empty: ParseResult = { nodes: [], edges: [] };
  const regs = {
    // deliberately inserted OUT of order to prove assemble sorts on insert
    "pricing.features.yaml": "- id: pfl.scenario\n  label: Scenario modeling\n",
    "onboarding.features.yaml": "- id: add.mapping\n  label: Column mapping\n",
  };

  it("carries registries keyed by basename with byte-exact content, keys sorted", () => {
    const g = assemble(empty, "T", regs);
    expect(g.registries).toBeDefined();
    expect(Object.keys(g.registries!)).toEqual(["onboarding.features.yaml", "pricing.features.yaml"]);
    expect(g.registries!["onboarding.features.yaml"]).toBe("- id: add.mapping\n  label: Column mapping\n");
    expect(g.registries!["pricing.features.yaml"]).toBe("- id: pfl.scenario\n  label: Scenario modeling\n");
  });

  it("omits the registries key entirely when none are provided (no artifact churn)", () => {
    expect("registries" in assemble(empty, "T")).toBe(false);
    expect("registries" in assemble(empty, "T", {})).toBe(false);
  });

  it("serializes deterministically: two assembles produce the identical JSON string", () => {
    const a = assemble(empty, "T", { ...regs });
    // second call with the SAME entries inserted in the opposite order
    const flipped = Object.fromEntries(Object.entries(regs).reverse());
    const b = assemble(empty, "T", flipped);
    expect(JSON.stringify(a.registries)).toBe(JSON.stringify(b.registries));
    expect(JSON.stringify(a)).toBe(JSON.stringify(b));
  });

  it("does not add issues or nodes/edges (viewer-only payload)", () => {
    const g = assemble(empty, "T", regs);
    expect(g.nodes).toEqual([]);
    expect(g.edges).toEqual([]);
    expect(g.issues).toEqual([]);
  });
});

/**
 * REQ-KG-CORE-07 — a `status: draft` doc is a PROPOSAL, and the ratchet must not count proposals.
 *
 * Found by dogfooding `kg-draft-spec` on this repo: drafting one doc raised `uncovered-requirement`
 * by four and `unverified-doc` by one, and `check --update-baseline` only ever LOWERS — so there was
 * no sanctioned way to accept the rise. The product's own recommended first move on an unspecced repo
 * left `npm run check` permanently red, and the only ways out were deleting the draft or refreshing a
 * baseline, which is the one move this project never makes.
 *
 * A draft has not claimed anything yet, so there is nothing to have failed to prove. It becomes
 * countable the moment the CEO promotes it.
 */
describe("assemble — a draft doc is a proposal, not an unmet promise", () => {
  const draftParts = (status: string): ParseResult => ({
    nodes: [
      { id: "d", type: "doc", title: "Drafted", status, entrypoint: true },
      { id: "REQ-D-1", type: "requirement", title: "drafted claim" },
    ],
    edges: [{ from: "d", to: "REQ-D-1", type: "specifies", source: "doc" }],
  });

  it("does not count a drafted requirement as uncovered", () => {
    const g = assemble(draftParts("draft"), "T");
    expect(g.issues.filter((i) => i.kind === "uncovered-requirement")).toHaveLength(0);
  });

  it("does not count a draft doc as unverified", () => {
    const g = assemble(draftParts("draft"), "T");
    expect(g.issues.filter((i) => i.kind === "unverified-doc")).toHaveLength(0);
  });

  // The exemption must be the DRAFT status doing the work, not the shape of the fixture — otherwise
  // this passes for a reason that has nothing to do with what it claims to test.
  it("counts both the moment the same doc is promoted to current", () => {
    const g = assemble(draftParts("current"), "T");
    expect(g.issues.filter((i) => i.kind === "uncovered-requirement")).toHaveLength(1);
    expect(g.issues.filter((i) => i.kind === "unverified-doc")).toHaveLength(1);
  });

  // A requirement an approved doc also specifies is a real promise; a draft restating it must not
  // launder it out of the ratchet.
  it("still counts a requirement that any non-draft doc specifies", () => {
    const parts: ParseResult = {
      nodes: [
        { id: "draft", type: "doc", title: "Drafted", status: "draft", entrypoint: true },
        { id: "real", type: "doc", title: "Approved", status: "current", entrypoint: true },
        { id: "REQ-X-1", type: "requirement", title: "shared claim" },
      ],
      edges: [
        { from: "draft", to: "REQ-X-1", type: "specifies", source: "doc" },
        { from: "real", to: "REQ-X-1", type: "specifies", source: "doc" },
      ],
    };
    expect(assemble(parts, "T").issues.filter((i) => i.kind === "uncovered-requirement")).toHaveLength(1);
  });

  // A draft still has to be reachable, or drafts accumulate as unlinked strays.
  it("still flags an unlinked draft as an orphan", () => {
    const parts: ParseResult = {
      nodes: [{ id: "d", type: "doc", title: "Drafted", status: "draft" }],
      edges: [],
    };
    expect(assemble(parts, "T").issues.filter((i) => i.kind === "orphan-doc")).toHaveLength(1);
  });
});

// covers: REQ-KG-01
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { graphsMatch, viewerMatches, countIssuesByKind, ratchetFailures, lowerBaseline } from "./check";
import { renderViewer } from "./viewer";
import type { Graph, Issue } from "./types";

// The REAL production template — the freshness gate compares against a viewer rendered from it, so
// the date-normalization regression must be proven against the real thing, not a toy template.
const REAL_TEMPLATE = readFileSync(join(dirname(fileURLToPath(import.meta.url)), "..", "viewer.template.html"), "utf8");

const base: Graph = {
  generatedAt: "2026-07-01T00:00:00Z",
  nodes: [{ id: "n1", type: "doc", title: "Node 1", status: "current", entrypoint: true }],
  edges: [],
  issues: [],
};

describe("graphsMatch", () => {
  it("returns true for identical graphs", () => {
    expect(graphsMatch(base, { ...base })).toBe(true);
  });

  it("returns true when graphs differ only in generatedAt", () => {
    const fresh: Graph = { ...base, generatedAt: "2026-07-02T12:00:00Z" };
    expect(graphsMatch(base, fresh)).toBe(true);
  });

  it("returns false when nodes differ", () => {
    const fresh: Graph = {
      ...base,
      nodes: [{ id: "n2", type: "doc", title: "Node 2", status: "current", entrypoint: true }],
    };
    expect(graphsMatch(base, fresh)).toBe(false);
  });

  it("returns false when edges differ", () => {
    const fresh: Graph = {
      ...base,
      edges: [{ from: "n1", to: "n2", type: "references", source: "doc" }],
    };
    expect(graphsMatch(base, fresh)).toBe(false);
  });

  it("returns false when issues differ", () => {
    const fresh: Graph = {
      ...base,
      issues: [{ kind: "orphan-doc", node: "n1", detail: "no inbound references/imports" }],
    };
    expect(graphsMatch(base, fresh)).toBe(false);
  });
});

// created/updated are git commit dates — as volatile as generatedAt (they change whenever a dated
// .md is committed on a new calendar day), so they MUST be excluded from the freshness fingerprint
// or `npm run check` false-fails STALE. reviewedAt is frontmatter-derived (content) and MUST stay.
describe("graphsMatch — volatile git dates (created/updated) excluded, reviewedAt kept", () => {
  const dated = (created: string, updated: string, title = "Node 1"): Graph => ({
    generatedAt: "2026-07-01T00:00:00Z",
    nodes: [{ id: "n1", type: "doc", title, path: "svc_backend/.github/x.md", created, updated }],
    edges: [],
    issues: [],
  });

  it("returns true when two graphs differ ONLY in a node's created/updated", () => {
    expect(graphsMatch(dated("2026-01-01", "2026-06-01"), dated("2026-01-02", "2026-07-15"))).toBe(true);
  });

  it("still returns false for a real structural diff (node title) when dates are equal", () => {
    expect(graphsMatch(dated("2026-01-01", "2026-06-01", "Node 1"), dated("2026-01-01", "2026-06-01", "Node 1 RENAMED"))).toBe(false);
  });

  it("keeps reviewedAt in the fingerprint — a frontmatter last_reviewed change still triggers rebuild", () => {
    const a: Graph = { generatedAt: "T", nodes: [{ id: "n1", type: "doc", title: "N", reviewedAt: "2026-01-01" }], edges: [], issues: [] };
    const b: Graph = { generatedAt: "T", nodes: [{ id: "n1", type: "doc", title: "N", reviewedAt: "2026-05-05" }], edges: [], issues: [] };
    expect(graphsMatch(a, b)).toBe(false);
  });
});

describe("viewerMatches", () => {
  it("ignores the embedded generatedAt", () => {
    const a = `x"generatedAt":"2026-01-01T00:00:00Z"y`;
    const b = `x"generatedAt":"2026-07-02T09:00:00Z"y`;
    expect(viewerMatches(a, b)).toBe(true);
  });

  it("detects real content drift", () => {
    expect(viewerMatches(`x"nodes":[1]`, `x"nodes":[2]`)).toBe(false);
  });

  it("ignores the injected DELTA block (sync vs build must both be fresh)", () => {
    const a = 'x /*__KG_DELTA__*/null/*__KG_END_DELTA__*/ y "generatedAt":"1"';
    const b = 'x /*__KG_DELTA__*/{"added":[]}/*__KG_END_DELTA__*/ y "generatedAt":"2"';
    expect(viewerMatches(a, b)).toBe(true);
  });

  // Regression: once the tool indexes its own *.test.ts files as unit nodes, a node's inlined
  // `source` field can legitimately contain the LITERAL marker text (this exact fixture in
  // viewer.test.ts / check.test.ts is proof). A naive `.replace(...)` (non-global) on the whole
  // committed/fresh viewer.html string strips the FIRST /*__KG_DELTA__*/…/*__KG_END_DELTA__*/
  // span it finds — which sits INSIDE the data blob (the decoy) — and never reaches the REAL
  // template span after it, so the real trailing delta is left un-normalized and a legitimately
  // fresh (delta non-null) sync-written viewer.html false-fails as STALE against the committed
  // (delta null) one. The two strings below simulate that: an earlier decoy marker span embedded
  // in a simulated data blob (identical in both), followed by the REAL trailing delta span, which
  // is the only thing that actually differs.
  describe("marker collision: decoy DELTA span embedded in data blob before the real one", () => {
    const decoy = '"source":"const s = \'/*__KG_DELTA__*/null/*__KG_END_DELTA__*/\';"';

    it("normalizes via the LAST (real, trailing) DELTA span even with an earlier decoy", () => {
      const a = `{${decoy}} /*__KG_DELTA__*/null/*__KG_END_DELTA__*/ "generatedAt":"1"`;
      const b = `{${decoy}} /*__KG_DELTA__*/{"added":[1]}/*__KG_END_DELTA__*/ "generatedAt":"2"`;
      expect(viewerMatches(a, b)).toBe(true);
    });

    it("still detects real drift when the REAL trailing span differs in kind, not just the decoy", () => {
      const a = `{${decoy}} /*__KG_DELTA__*/null/*__KG_END_DELTA__*/ "nodes":[1]`;
      const b = `{${decoy}} /*__KG_DELTA__*/null/*__KG_END_DELTA__*/ "nodes":[2]`;
      expect(viewerMatches(a, b)).toBe(false);
    });
  });

  // Rendered from the REAL template: two viewers whose only difference is a node's git
  // created/updated must compare fresh, or `npm run check` false-fails STALE on any cross-day commit
  // of a dated .md. A real content diff (node title) must still be caught.
  describe("volatile git dates (created/updated) blanked in the rendered viewer (real template)", () => {
    const render = (created: string, updated: string, title = "Foo"): string =>
      renderViewer(
        {
          generatedAt: "2026-07-01T00:00:00Z",
          nodes: [
            { id: "backend:foo", type: "doc", title, path: "svc_backend/.github/system-design/foo.md", created, updated },
          ],
          edges: [],
          issues: [],
        } as unknown as Graph,
        REAL_TEMPLATE,
      );

    it("treats two viewers that differ ONLY in a node's created/updated as fresh", () => {
      expect(viewerMatches(render("2026-01-01", "2026-06-01"), render("2026-01-02", "2026-07-15"))).toBe(true);
    });

    it("still flags a real structural diff (node title) as stale", () => {
      expect(viewerMatches(render("2026-01-01", "2026-06-01", "Foo"), render("2026-01-01", "2026-06-01", "Foo RENAMED"))).toBe(false);
    });

    it("keeps reviewedAt drift stale (frontmatter change must rebuild the viewer)", () => {
      const withReview = (reviewedAt: string): string =>
        renderViewer(
          { generatedAt: "T", nodes: [{ id: "backend:foo", type: "doc", title: "Foo", reviewedAt }], edges: [], issues: [] } as unknown as Graph,
          REAL_TEMPLATE,
        );
      expect(viewerMatches(withReview("2026-01-01"), withReview("2026-05-05"))).toBe(false);
    });
  });
});

const issues = (kinds: string[]): Issue[] => kinds.map((kind) => ({ kind, detail: "x" }));

describe("countIssuesByKind", () => {
  it("tallies issues per kind", () => {
    expect(countIssuesByKind(issues(["orphan-doc", "orphan-doc", "broken-link"]))).toEqual({
      "orphan-doc": 2,
      "broken-link": 1,
    });
  });

  it("returns an empty tally for no issues", () => {
    expect(countIssuesByKind([])).toEqual({});
  });
});

describe("ratchetFailures", () => {
  it("passes when every kind is at or below its baseline", () => {
    const baseline = { "orphan-doc": 143, "broken-link": 9 };
    expect(ratchetFailures(baseline, { "orphan-doc": 143, "broken-link": 8 })).toEqual([]);
  });

  it("fails a kind that rose above baseline", () => {
    const baseline = { "orphan-doc": 143 };
    expect(ratchetFailures(baseline, { "orphan-doc": 144 })).toEqual([
      { kind: "orphan-doc", baseline: 143, actual: 144 },
    ]);
  });

  it("treats a kind absent from the baseline as baseline 0 (blocks immediately)", () => {
    // untracked-e2e is baselined at 0 → any occurrence must fail the gate.
    expect(ratchetFailures({}, { "untracked-e2e": 1 })).toEqual([
      { kind: "untracked-e2e", baseline: 0, actual: 1 },
    ]);
  });

  it("does not fail when a baselined kind disappears", () => {
    expect(ratchetFailures({ "broken-link": 9 }, {})).toEqual([]);
  });
});

describe("lowerBaseline", () => {
  it("lowers a count when issues were fixed", () => {
    expect(lowerBaseline({ "orphan-doc": 143 }, { "orphan-doc": 140 })).toEqual({ "orphan-doc": 140 });
  });

  it("never raises a count (a regression cannot be papered over)", () => {
    expect(lowerBaseline({ "orphan-doc": 143 }, { "orphan-doc": 150 })).toEqual({ "orphan-doc": 143 });
  });

  it("records a brand-new kind at its current count", () => {
    expect(lowerBaseline({}, { "untracked-e2e": 2 })).toEqual({ "untracked-e2e": 2 });
  });

  it("drops a kind to 0 once fully resolved", () => {
    expect(lowerBaseline({ "broken-link": 9 }, {})).toEqual({ "broken-link": 0 });
  });
});

// covers: REQ-KG-CONF-02
import { describe, it, expect } from "vitest";
import { codeCandidatePairs, declaredSymbols, isProofFile } from "./codeCandidates";

/**
 * REQ-KG-CONF-02, code half. A project arriving with code and no docs has no `governs:`, no
 * requirements and no registries — so the doc-anchored enumerator yields ZERO pairs and the scan finds
 * nothing at all. That is the customer the product is for, so the surface has to reach code directly.
 *
 * The bound moves; it does not disappear. Pairs come from a SHARED DECLARED SYMBOL: two files that
 * declare no name in common never become a candidate, and a name declared everywhere is not a signal.
 */

const tax = {
  path: "src/billing/tax.ts",
  text: `export const TAX_BASIS = "subtotal";\nexport function applyTax(order) { return order.subtotal * 0.2; }\n`,
};
const invoice = {
  path: "src/invoice/render.py",
  text: `TAX_BASIS = "discounted_total"\ndef apply_tax(order):\n    return order.discounted_total * 0.2\n`,
};
const unrelated = {
  path: "src/mailer.ts",
  text: `export function sendMail(to) { return fetch("/mail", { body: to }); }\n`,
};

describe("declaredSymbols", () => {
  it("picks up declarations across languages", () => {
    expect(declaredSymbols(tax.text)).toEqual(expect.arrayContaining(["TAX_BASIS", "applyTax"]));
    expect(declaredSymbols(invoice.text)).toEqual(expect.arrayContaining(["TAX_BASIS", "apply_tax"]));
  });

  // Short and ubiquitous names pair everything with everything — the combinatorial explosion that
  // makes a surface useless rather than merely large.
  it("ignores names too short to carry meaning", () => {
    expect(declaredSymbols("const x = 1;\nconst id = 2;\n")).toEqual([]);
  });

  // A rule lives on a module's surface. A working variable inside a function body shares its name with
  // half the codebase by coincidence, and matching those was 149 junk pairs on this repo alone.
  it("ignores locals inside a function body, and keeps the module's own surface", () => {
    const text = [
      "export const RETRY_LIMIT = 3;",
      "export function retry(job) {",
      "  const results = [];",
      "  let attempts = 0;",
      "  return results;",
      "}",
    ].join("\n");
    expect(declaredSymbols(text)).toEqual(["RETRY_LIMIT", "retry"]);
  });
});

/**
 * Measured on this repo before this existed: 164 of 280 code pairs involved a test file — two suites
 * both declaring `CONFIG` or `PINNED`, which is a shared fixture convention, not a disagreement.
 * Behaviour lives in source; tests are the proof of it. A surface that is 59% noise is the failure
 * §12.10 describes, where the CEO stops opening the inbox.
 */
describe("isProofFile", () => {
  it("recognises tests by the project's own declared globs", () => {
    expect(isProofFile("src/checkout.test.ts", { unitTestGlobs: ["src/**/*.test.ts"], e2eDir: "e2e" })).toBe(true);
    expect(isProofFile("e2e/checkout.spec.ts", { unitTestGlobs: [], e2eDir: "e2e" })).toBe(true);
    expect(isProofFile("src/checkout.ts", { unitTestGlobs: ["src/**/*.test.ts"], e2eDir: "e2e" })).toBe(false);
  });

  // A project that declares no globs still must not have its suites treated as behaviour.
  it("falls back to the near-universal filename convention when a project declares nothing", () => {
    expect(isProofFile("lib/thing.spec.js", { unitTestGlobs: [], e2eDir: "" })).toBe(true);
    expect(isProofFile("tests/test_rates.py", { unitTestGlobs: [], e2eDir: "" })).toBe(true);
    expect(isProofFile("lib/thing.js", { unitTestGlobs: [], e2eDir: "" })).toBe(false);
  });
});

describe("codeCandidatePairs", () => {
  it("pairs two files that declare the same symbol", () => {
    const pairs = codeCandidatePairs([tax, invoice, unrelated]);
    expect(pairs).toHaveLength(1);
    expect(pairs[0]).toMatchObject({ kind: "code-code", a: "src/billing/tax.ts", b: "src/invoice/render.py" });
  });

  it("never pairs files with no shared declaration", () => {
    expect(codeCandidatePairs([tax, unrelated])).toEqual([]);
  });

  // A symbol every file declares (a framework hook, a re-exported helper) says nothing about either
  // file. Precision is the whole product here, so ubiquity disqualifies.
  it("drops a symbol declared in too many files to be distinctive", () => {
    const many = Array.from({ length: 9 }, (_, i) => ({
      path: `src/mod${i}.ts`,
      text: `export function handleRequest(){}\n`,
    }));
    expect(codeCandidatePairs(many, { maxFilesPerSymbol: 5 })).toEqual([]);
  });

  it("is deterministic and deduped — the same tree always enumerates the same surface", () => {
    const third = { path: "src/zzz/legacy.ts", text: `const TAX_BASIS = "gross";\nfunction applyTax(){}\n` };
    const once = codeCandidatePairs([tax, invoice, third]);
    const again = codeCandidatePairs([third, invoice, tax]);
    expect(once).toEqual(again);
    // Two shared symbols between the same two files is still ONE pair to adjudicate.
    expect(once.filter((p) => p.a === "src/billing/tax.ts" && p.b === "src/zzz/legacy.ts")).toHaveLength(1);
  });

  // Without this the adjudicator has to re-derive, by reading two whole files, the one thing the
  // enumerator already knew: which name they have in common and therefore what to compare.
  it("says WHY the pair was made, so the reader knows what to compare", () => {
    const pairs = codeCandidatePairs([tax, invoice, unrelated]);
    expect(pairs[0].sharedSymbols).toEqual(["TAX_BASIS"]);
  });

  // A silent cap reads as "we looked at everything" when it did not.
  it("reports what a cap dropped instead of truncating quietly", () => {
    const files = Array.from({ length: 12 }, (_, i) => ({ path: `src/f${i}.ts`, text: `const SHARED_RATE = ${i};\n` }));
    const { pairs, dropped } = codeCandidatePairs(files, { maxFilesPerSymbol: 20, limit: 5, withReport: true });
    expect(pairs).toHaveLength(5);
    expect(dropped).toBeGreaterThan(0);
  });
});

// covers: REQ-KG-CORE-02
import { describe, it, expect } from "vitest";
import { mkdtemp, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  parseConfig,
  loadConfig,
  repoOf,
  nsId,
  subdirOf,
  prefixOf,
  siblingsOf,
  knowledgeGlobs,
  e2ePath,
  artifactPath,
  stripRepoPrefix,
  CONFIG_FILE,
  type Repos,
  type Config,
} from "./config";

/**
 * Phase 2 — the topology, the paths and the runners get ONE owner (founding design §10.8, §10.9).
 *
 * The topology used to be re-declared in four places: repo.ts (as a union TYPE), gitDates.ts, serve.ts,
 * and sources.ts — the third independent copy, added by the gate work a day earlier. The pattern was
 * still reproducing, which is why collapsing it is the defect rather than scope creep.
 */

/** A three-repo workspace: one root plus two nested siblings. The shape REQ-0 is measured against. */
const TRIO: Repos = [
  { name: "main", subdir: "" },
  { name: "backend", subdir: "svc_backend" },
  { name: "frontend", subdir: "svc_frontend" },
];

/** The degenerate case, and the one that proves "reusable" is real rather than aspirational. */
const SOLO: Repos = [{ name: "main", subdir: "" }];

const cfg = (json: unknown) => parseConfig(JSON.stringify(json));

describe("parseConfig — a half-valid config must never load", () => {
  it("accepts a well-formed topology", () => {
    expect(cfg({ repos: TRIO }).repos).toEqual(TRIO);
  });

  // A partial topology silently misfiles every node in the missing repo — the same class of failure as
  // the report-only gate: confidently wrong beats obviously broken, and costs more.
  it("rejects a config with no repos at all", () => {
    expect(() => cfg({ repos: [] })).toThrow(/repos/i);
    expect(() => cfg({})).toThrow(/repos/i);
  });

  it("rejects a topology with no root repo — something must own the workspace root", () => {
    expect(() => cfg({ repos: [{ name: "backend", subdir: "b" }] })).toThrow(/root/i);
  });

  it("rejects two root repos — the root cannot be ambiguous", () => {
    expect(() => cfg({ repos: [{ name: "a", subdir: "" }, { name: "b", subdir: "" }] })).toThrow(/root/i);
  });

  it("rejects duplicate repo names — ids would collide silently", () => {
    expect(() => cfg({ repos: [{ name: "main", subdir: "" }, { name: "main", subdir: "x" }] })).toThrow(/duplicate|main/i);
  });

  it("rejects unparseable json rather than yielding an empty topology", () => {
    expect(() => parseConfig("{not json")).toThrow();
  });

  // A runner naming a repo that does not exist would spawn a server in the wrong directory — or, with
  // a silent fallback, in the workspace root. Both are worse than refusing to start.
  it("rejects a runner pointed at a repo that does not exist", () => {
    expect(() => cfg({ repos: SOLO, runners: { backend: "nope" } })).toThrow(/nope/i);
  });
});

describe("parseConfig — defaults let a simple project say almost nothing", () => {
  it("fills every path from a repos-only config", () => {
    const c = cfg({ repos: SOLO });
    expect(c.e2eDir).toBe("e2e");
    expect(c.artifactDir).toBe("knowledge-graph");
    expect(c.unitTestGlobs).toEqual([]);
    expect(c.runners).toEqual({ backend: null, frontend: null });
  });

  it("takes explicit paths over the defaults", () => {
    const c = cfg({ repos: TRIO, e2eDir: "svc_frontend/e2e", artifactDir: "tools/kg" });
    expect(c.e2eDir).toBe("svc_frontend/e2e");
    expect(c.artifactDir).toBe("tools/kg");
  });

  it("strips trailing slashes so derived paths never double up", () => {
    expect(cfg({ repos: SOLO, e2eDir: "e2e/" }).e2eDir).toBe("e2e");
    expect(cfg({ repos: SOLO, artifactDir: "tools/kg//" }).artifactDir).toBe("tools/kg");
  });
});

describe("repoOf — derives the owning repo from a path, per config", () => {
  it("matches the longest subdir prefix", () => {
    expect(repoOf("svc_backend/services/x.py", TRIO)).toBe("backend");
    expect(repoOf("svc_frontend/src/a.ts", TRIO)).toBe("frontend");
  });

  it("falls back to the root repo when nothing else matches", () => {
    expect(repoOf("tools/knowledge-graph/src/x.ts", TRIO)).toBe("main");
    expect(repoOf(undefined, TRIO)).toBe("main");
  });

  // A prefix must be a PATH boundary, not a string prefix: "svc_backend_old/" is not the backend.
  it("only matches on a path boundary", () => {
    expect(repoOf("svc_backend_old/x.py", TRIO)).toBe("main");
  });

  it("prefers the deeper repo when one nests inside another", () => {
    const nested: Repos = [
      { name: "main", subdir: "" },
      { name: "outer", subdir: "packages" },
      { name: "inner", subdir: "packages/web" },
    ];
    expect(repoOf("packages/web/src/a.ts", nested)).toBe("inner");
    expect(repoOf("packages/api/src/a.ts", nested)).toBe("outer");
  });

  it("works for a single-repo project — everything is the root", () => {
    expect(repoOf("src/discover.ts", SOLO)).toBe("main");
    expect(repoOf("anything/at/all.md", SOLO)).toBe("main");
  });
});

describe("nsId — namespaces a bare id by its owning repo", () => {
  it("prefixes with the repo name", () => {
    expect(nsId("svc_backend/.github/system-design/x.md", "sd-56", TRIO)).toBe("backend:sd-56");
    expect(nsId("tools/x/y.ts", "thing", TRIO)).toBe("main:thing");
  });

  it("namespaces by the root repo in a single-repo project", () => {
    expect(nsId("docs/x.md", "thing", SOLO)).toBe("main:thing");
  });
});

describe("subdirOf / prefixOf — the maps gitDates, sources and serve each re-declared", () => {
  it("resolves a repo's subdir and path prefix from config", () => {
    expect(subdirOf("backend", TRIO)).toBe("svc_backend");
    expect(prefixOf("backend", TRIO)).toBe("svc_backend/");
  });

  it("gives the root repo an empty subdir and an empty prefix", () => {
    expect(subdirOf("main", TRIO)).toBe("");
    expect(prefixOf("main", TRIO)).toBe("");
  });

  it("throws on a repo the topology never declared", () => {
    expect(() => subdirOf("frontend", SOLO)).toThrow(/frontend/i);
  });
});

describe("siblingsOf — the non-root repos, in config order (sources.ts's SIBLINGS)", () => {
  it("lists every repo but the root, preserving order", () => {
    expect(siblingsOf(TRIO).map((r) => r.name)).toEqual(["backend", "frontend"]);
  });

  // The lockfile pins SIBLINGS. A single-repo project has none — and must not therefore be unpinnable
  // by definition; it simply has nothing to pin.
  it("is empty for a single-repo project", () => {
    expect(siblingsOf(SOLO)).toEqual([]);
  });
});

describe("stripRepoPrefix — a path relative to its OWN repo, not the workspace", () => {
