describe("loadConfig — reads the project's config from its own root", () => {
  const write = async (body: unknown) => {
    const dir = await mkdtemp(join(tmpdir(), "kg-config-"));
    await writeFile(join(dir, CONFIG_FILE), JSON.stringify(body));
    return dir;
  };

  it("loads and validates the file at the repo root", async () => {
    const dir = await write({ repos: TRIO, artifactDir: "tools/kg" });
    const c = await loadConfig(dir);
    expect(c.repos).toEqual(TRIO);
    expect(c.artifactDir).toBe("tools/kg");
  });

  /**
   * NO SILENT DEFAULT. A missing config could plausibly fall back to a single-repo topology — and that
   * is exactly the trap: against a multi-repo workspace it would namespace every backend node `main:`
   * instead of `backend:`, producing a complete, confident, wrong graph. Same class as the `|| echo`
   * gate. Refusing costs one error message; guessing costs a silently different SSoT.
   */
  it("refuses to guess when the project has no config", async () => {
    const dir = await mkdtemp(join(tmpdir(), "kg-noconfig-"));
    await expect(loadConfig(dir)).rejects.toThrow(new RegExp(CONFIG_FILE));
  });

  it("names the file when it is unreadable garbage", async () => {
    const dir = await mkdtemp(join(tmpdir(), "kg-badconfig-"));
    await writeFile(join(dir, CONFIG_FILE), "{not json");
    await expect(loadConfig(dir)).rejects.toThrow();
  });
});

/**
 * `exclude` — sub-trees that are NOT this project's knowledge (CEO 2026-07-24).
 *
 * The knowledge globs are deliberately repo-wide (`**\/CLAUDE.md`, `**\/.github/**\/*.md`) because the
 * tool defines where knowledge lives in ANY project. That is right until a repo contains a *second*
 * project as data — committed fixtures, samples, vendored trees — whose docs then get indexed as the
 * host's own. Self-hosting found it: this repo's REQ-1 fixtures collided on `main:claude` and
 * contributed four docs and three requirements that are not ours.
 *
 * It lives in config, never in the tool, because a hardcoded `fixtures/**` would re-introduce exactly
 * the project-specific coupling REQ-0 removed.
 */
const base = { repos: [{ name: "main", subdir: "" }] };
describe("exclude", () => {
  it("defaults to excluding nothing", () => {
    expect(parseConfig(JSON.stringify(base)).exclude).toEqual([]);
  });

  it("keeps a declared sub-tree out of the graph", () => {
    const c = parseConfig(JSON.stringify({ ...base, exclude: ["fixtures/**", "samples/**"] }));
    expect(c.exclude).toEqual(["fixtures/**", "samples/**"]);
  });

  it("rejects a non-array exclude rather than silently ignoring it", () => {
    expect(() => parseConfig(JSON.stringify({ ...base, exclude: "fixtures/**" }))).toThrow(/exclude/);
  });

  it("rejects non-string entries", () => {
    expect(() => parseConfig(JSON.stringify({ ...base, exclude: ["ok", 7] }))).toThrow(/exclude/);
  });
});

/**
 * `evidence` — exactly ONE declared destination for run screenshots (CEO 2026-07-24).
 *
 * A discriminated union rather than several independently-settable fields, deliberately: a config
 * that could carry both a blob URL and a GitHub repo would have no defined winner, and something
 * downstream would silently pick one. That is precisely the failure this tool exists to detect, so
 * its own config must not commit it.
 *
 * Omitted means local device — the honest fallback, and the one with no shared baseline for
 * flow-approval to diff against.
 */
describe("evidence destination", () => {
  it("falls back to the local device when nothing is declared", () => {
    expect(parseConfig(JSON.stringify(base)).evidence).toEqual({ kind: "local" });
  });

  // Coordinates only — NEVER a credential. kg.config.json is committed, so a signed URL or a key in
  // it would land in git history permanently. Credentials come from the standard AWS chain at run
  // time (env, ~/.aws, instance role, or CI's OIDC-minted short-lived creds).
  it("takes a blob bucket, prefix and region", () => {
    const c = parseConfig(JSON.stringify({ ...base, evidence: { kind: "blob", bucket: "acme-kg", prefix: "kg-cases/", region: "us-east-1" } }));
    expect(c.evidence).toEqual({ kind: "blob", bucket: "acme-kg", prefix: "kg-cases", region: "us-east-1" });
  });

  it("defaults the prefix to the bucket root", () => {
    const c = parseConfig(JSON.stringify({ ...base, evidence: { kind: "blob", bucket: "acme-kg", region: "us-east-1" } }));
    expect(c.evidence).toEqual({ kind: "blob", bucket: "acme-kg", prefix: "", region: "us-east-1" });
  });

  it("rejects a credential smuggled into the committed config", () => {
    const withKey = { ...base, evidence: { kind: "blob", bucket: "b", region: "r", secretAccessKey: "AKIA..." } };
    expect(() => parseConfig(JSON.stringify(withKey))).toThrow(/credential/i);
  });

  it("takes the tool-managed github evidence branch", () => {
    const c = parseConfig(JSON.stringify({ ...base, evidence: { kind: "github", repo: "acme/web" } }));
    expect(c.evidence).toEqual({ kind: "github", repo: "acme/web" });
  });

  it("accepts an explicit local declaration", () => {
    expect(parseConfig(JSON.stringify({ ...base, evidence: { kind: "local" } })).evidence).toEqual({ kind: "local" });
  });

  // Each of these would otherwise degrade into "store locally", which loses evidence silently — the
  // report-only failure mode again: confidently wrong beats obviously broken, and costs more.
  it("rejects a blob destination with no bucket", () => {
    expect(() => parseConfig(JSON.stringify({ ...base, evidence: { kind: "blob", region: "us-east-1" } }))).toThrow(/bucket/i);
  });

  // Without a region the object URL cannot be composed, so evidence would upload and then be
  // unaddressable — the worst of both outcomes.
  it("rejects a blob destination with no region", () => {
    expect(() => parseConfig(JSON.stringify({ ...base, evidence: { kind: "blob", bucket: "acme-kg" } }))).toThrow(/region/i);
  });

  it("rejects a github destination with no repo", () => {
    expect(() => parseConfig(JSON.stringify({ ...base, evidence: { kind: "github" } }))).toThrow(/repo/i);
  });

  it("rejects an unknown kind rather than silently storing locally", () => {
    expect(() => parseConfig(JSON.stringify({ ...base, evidence: { kind: "ftp", url: "x" } }))).toThrow(/evidence/i);
  });
});

// covers: REQ-KG-CONF-02
import { describe, it, expect } from "vitest";
import { enumerateCandidates } from "./conflictCandidates";
import type { Graph, GraphNode, GraphEdge } from "./types";

const doc = (id: string, domain?: string): GraphNode => ({ id, type: "doc", title: id, domain });
const req = (id: string): GraphNode => ({ id, type: "requirement", title: id });
const test = (id: string): GraphNode => ({ id, type: "test", title: id });
const edge = (from: string, to: string, type: GraphEdge["type"]): GraphEdge => ({ from, to, type, source: "x" });
const graph = (nodes: GraphNode[], edges: GraphEdge[]): Graph => ({ generatedAt: "", nodes, edges, issues: [] });

describe("enumerateCandidates", () => {
  it("pairs docs linked by a references edge (doc-doc)", () => {
    const g = graph([doc("main:a", "pfl"), doc("main:b", "pfl")], [edge("main:a", "main:b", "references")]);
    expect(enumerateCandidates(g)).toContainEqual({ kind: "doc-doc", a: "main:a", b: "main:b" });
  });
  it("pairs a doc with the code path it governs (doc-code)", () => {
    const g = graph([doc("main:a")], [edge("main:a", "services/x/", "governs")]);
    expect(enumerateCandidates(g)).toContainEqual({ kind: "doc-code", a: "main:a", b: "services/x/" });
  });
  it("pairs a requirement with the test that covers it (req-test)", () => {
    const g = graph([req("REQ-1"), test("T-1")], [edge("T-1", "REQ-1", "covers")]);
    expect(enumerateCandidates(g)).toContainEqual({ kind: "req-test", a: "REQ-1", b: "T-1" });
  });
  it("never emits a pair for two nodes with no connecting edge (no free-hunting)", () => {
    const g = graph([doc("main:a", "pfl"), doc("main:b", "pfl")], []);
    expect(enumerateCandidates(g)).toEqual([]);
  });
  it("dedupes reciprocal references into one unordered pair, sorted", () => {
    const g = graph(
      [doc("main:b", "pfl"), doc("main:a", "pfl")],
      [edge("main:b", "main:a", "references"), edge("main:a", "main:b", "references")],
    );
    expect(enumerateCandidates(g)).toEqual([{ kind: "doc-doc", a: "main:a", b: "main:b" }]);
  });
  it("filters doc-anchored pairs to the requested scope (by doc domain)", () => {
    const g = graph(
      [doc("main:a", "pfl"), doc("main:b", "pfl"), doc("main:c", "bil"), doc("main:d", "bil")],
      [edge("main:a", "main:b", "references"), edge("main:c", "main:d", "references")],
    );
    expect(enumerateCandidates(g, "pfl")).toEqual([{ kind: "doc-doc", a: "main:a", b: "main:b" }]);
  });
});

// covers: REQ-KG-CONF-02, REQ-KG-CONF-06
import { describe, it, expect, beforeAll, afterAll } from "vitest";
import { execFile } from "node:child_process";
import { mkdtemp, mkdir, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { promisify } from "node:util";
import { conflictId } from "./conflictId";

/**
 * The two conflict entrypoints the kg-scan-conflicts / kg-fix-conflicts skills invoke.
 *
 * They resolved the graph from the TOOL's own directory (`__dirname/..`), which is §10.9's second
 * coupling class: true only while the tool lives inside the artifact dir it measures. Installed as a
 * plugin it never does, so both CLIs died with ENOENT on every project — the skills had no working
 * entrypoint at all. These tests pin the project resolution (`KG_REPO_ROOT` / cwd + `artifactDir`)
 * rather than the tool's location, so the coupling cannot come back.
 *
 * Spawned as real processes on purpose: the defect lived entirely in the CLI glue, so an in-process
 * import of the pure functions would have stayed green throughout.
 */
const run = promisify(execFile);
const TOOL = join(__dirname, "..");

let root: string;
const SUBJECT = "sales tax basis";
const SCOPE = "billing";
const ID = conflictId(SUBJECT, SCOPE);

/** A project whose artifact dir is `artifacts/` — deliberately NOT the tool's own `knowledge-graph/`,
 *  so a CLI that ignored config could not accidentally pass. */
const graph = {
  generatedAt: "2000-01-01T00:00:00.000Z",
  nodes: [
    { id: "main:billing-spec", type: "doc", title: "Billing", domain: "billing", body: "Tax on the subtotal.", path: ".github/system-design/BILLING.md" },
    { id: "main:invoice-spec", type: "doc", title: "Invoicing", domain: "billing", body: "Tax on the discounted total.", path: ".github/system-design/INVOICE.md" },
  ],
  edges: [{ from: "main:billing-spec", to: "main:invoice-spec", type: "references" }],
  issues: [],
  conflicts: [
    {
      id: ID, subject: SUBJECT, scope: SCOPE, category: "formula", severity: "high", axis: "doc", tags: [], why: "two bases",
      positions: [
        { id: "A", statement: "tax on the subtotal", heldBy: ["main:billing-spec"] },
        { id: "B", statement: "tax on the discounted total", heldBy: ["main:invoice-spec"] },
      ],
      participants: [
        { kind: "doc", ref: "main:billing-spec", quote: "Tax on the subtotal.", positionId: "A" },
        { kind: "doc", ref: "main:invoice-spec", quote: "Tax on the discounted total.", positionId: "B" },
      ],
    },
  ],
};

beforeAll(async () => {
  root = await mkdtemp(join(tmpdir(), "kg-conflict-cli-"));
  await writeFile(
    join(root, "kg.config.json"),
    JSON.stringify({ repos: [{ name: "main", subdir: "" }], artifactDir: "artifacts", e2eDir: "e2e", unitTestGlobs: [] }),
  );
  await mkdir(join(root, "artifacts", "conflicts"), { recursive: true });
  await writeFile(join(root, "artifacts", "knowledge-graph.json"), JSON.stringify(graph));
  await writeFile(
    join(root, "artifacts", "conflicts", "decisions.json"),
    JSON.stringify({ [ID]: { status: "resolved", positionId: "A", note: "subtotal is canon" } }),
  );
});
afterAll(async () => { await rm(root, { recursive: true, force: true }); });

/** Spawned from the TOOL's directory with KG_REPO_ROOT pointing elsewhere — the installed-plugin
 *  shape. A CLI reading `__dirname/..` would find the tool's own graph, not the project's. */
const cli = (script: string, ...args: string[]) =>
  run("npx", ["tsx", join(TOOL, "src", script), ...args], { cwd: TOOL, env: { ...process.env, KG_REPO_ROOT: root } });

describe("scanContext CLI — the scan skill's only input", () => {
  it("reads the graph from the PROJECT's artifactDir and emits its candidate pairs", async () => {
    const { stdout } = await cli("scanContext.ts");
    const out = JSON.parse(stdout);
    expect(out.count).toBe(1);
    expect(out.items[0].pair).toMatchObject({ kind: "doc-doc" });
    // Content from the project's graph, not the tool's — this is what makes the assertion load-bearing.
    expect(out.items.map((i: { a: { ref: string } }) => i.a.ref)).toContain("main:billing-spec");
  });

  it("honours --scope, so a scan can be run one domain at a time", async () => {
    const { stdout } = await cli("scanContext.ts", "--scope", "nothing-here");
    expect(JSON.parse(stdout).count).toBe(0);
  });

  // Without this the scan skill has to guess a scope name, or hardcode a path to the graph to go
  // looking for one — the layout coupling this tool exists to remove, reintroduced in prose.
  it("lists the scannable scopes and their pair counts", async () => {
    const { stdout } = await cli("scanContext.ts", "--scopes");
    expect(JSON.parse(stdout).scopes).toEqual([{ scope: "billing", pairs: 1 }]);
  });
});

/**
 * The customer the product is actually for: code, an AI agent, and nothing else. No `governs:`, no
 * requirements, no registries — so every doc-anchored edge is absent and the scan used to return a
 * bounded set of exactly zero, while `kg-init` step 4 promised contradictions found with no docs at
 * all. This is that promise, asserted.
 */
describe("scanContext CLI — a repo that arrived with no docs", () => {
  let bare: string;
  beforeAll(async () => {
    bare = await mkdtemp(join(tmpdir(), "kg-bare-repo-"));
    await writeFile(
      join(bare, "kg.config.json"),
      JSON.stringify({ repos: [{ name: "main", subdir: "" }], artifactDir: "artifacts", e2eDir: "e2e", unitTestGlobs: [] }),
    );
    await mkdir(join(bare, "artifacts"), { recursive: true });
    // A graph with nothing in it — exactly what `npm run build` emits for a repo with no docs.
    await writeFile(join(bare, "artifacts", "knowledge-graph.json"), JSON.stringify({ generatedAt: "", nodes: [], edges: [], issues: [] }));
    await mkdir(join(bare, "src"), { recursive: true });
    // The same rule, implemented twice, disagreeing. No doc says which is right — that is the point.
    await writeFile(join(bare, "src", "checkout.ts"), 'export const TAX_BASIS = "subtotal";\nexport function applyTax(o){return o.subtotal*0.2;}\n');
    await writeFile(join(bare, "src", "invoice.py"), 'TAX_BASIS = "discounted_total"\ndef applyTax(o):\n    return o.discounted * 0.2\n');
    await writeFile(join(bare, "src", "mailer.ts"), "export function sendMail(to){return to;}\n");
  });
  afterAll(async () => { await rm(bare, { recursive: true, force: true }); });

  const bareCli = (...args: string[]) =>
    run("npx", ["tsx", join(TOOL, "src", "scanContext.ts"), ...args], { cwd: TOOL, env: { ...process.env, KG_REPO_ROOT: bare } });

  it("still yields a surface, from the code itself", async () => {
    const out = JSON.parse((await bareCli()).stdout);
    expect(out.count).toBeGreaterThan(0);
    const pair = out.items.find((i: any) => i.pair.kind === "code-code");
    expect(pair, "a repo with no docs must still produce code-code candidates").toBeTruthy();
    expect([pair.a.ref, pair.b.ref].sort()).toEqual(["src/checkout.ts", "src/invoice.py"]);
  });

  it("still pairs nothing that shares no declaration", async () => {
    const out = JSON.parse((await bareCli()).stdout);
    const refs = out.items.flatMap((i: any) => [i.a.ref, i.b.ref]);
    expect(refs).not.toContain("src/mailer.ts");
  });
});

describe("fixPlan CLI — what kg-fix-conflicts applies", () => {
  it("reads the project's graph and decisions, and plans only the dissenter", async () => {
    const { stdout } = await cli("fixPlan.ts");
    const out = JSON.parse(stdout);
    expect(out.count).toBe(1);
    expect(out.plans[0].canonicalStatement).toBe("tax on the subtotal");
    expect(out.plans[0].note).toBe("subtotal is canon");
    // Only the losing side is a target — the canonical participant must never be "fixed".
    expect(out.plans[0].targets.map((t: { ref: string }) => t.ref)).toEqual(["main:invoice-spec"]);
  });
});

import { describe, it, expect } from "vitest";
import { readDecisions, applyDecision, serializeDecisions, decisionsFor } from "./conflictDecisions";
import type { ConflictFinding } from "./types";

const finding = (id: string): ConflictFinding => ({
  id, subject: id, scope: "pfl", category: "formula", severity: "high", axis: "mixed", tags: [], why: "",
  participants: [], positions: [],
});

describe("readDecisions", () => {
  it("parses a decisions map", () => {
    expect(readDecisions(JSON.stringify({ "cf-1": { status: "dismissed" } }))).toEqual({ "cf-1": { status: "dismissed" } });
  });
  it("returns {} for null / malformed, never throws", () => {
    expect(readDecisions(null)).toEqual({});
    expect(readDecisions("{bad")).toEqual({});
    expect(readDecisions("[]")).toEqual({});
  });
});

describe("applyDecision", () => {
  it("stores a decision immutably", () => {
    const before = {};
    const after = applyDecision(before, "cf-1", { status: "dismissed", at: "t" });
    expect(after).toEqual({ "cf-1": { status: "dismissed", at: "t" } });
    expect(before).toEqual({}); // unchanged
  });
  it("overwrites an existing decision for the same id", () => {
    const after = applyDecision({ "cf-1": { status: "dismissed" } }, "cf-1", { status: "resolved", positionId: "A" });
    expect(after["cf-1"]).toEqual({ status: "resolved", positionId: "A" });
  });
  it("removes the entry when reset to open (finding returns to default)", () => {
    const after = applyDecision({ "cf-1": { status: "dismissed" } }, "cf-1", { status: "open" });
    expect(after["cf-1"]).toBeUndefined();
  });
});

describe("serializeDecisions", () => {
  it("emits keys in sorted order (stable, diffable)", () => {
    const s = serializeDecisions({ "cf-b": { status: "dismissed" }, "cf-a": { status: "resolved", positionId: "A" } });
    expect(s.indexOf("cf-a")).toBeLessThan(s.indexOf("cf-b"));
  });
});

describe("decisionsFor", () => {
  it("keeps only decisions whose finding still exists (prunes stale) and defaults missing to open", () => {
    const findings = [finding("cf-1"), finding("cf-2")];
    const decisions = { "cf-1": { status: "dismissed" as const }, "cf-gone": { status: "dismissed" as const } };
    const merged = decisionsFor(findings, decisions);
    expect(merged["cf-1"].status).toBe("dismissed");
    expect(merged["cf-2"].status).toBe("open"); // default
    expect(merged["cf-gone"]).toBeUndefined(); // pruned — its finding is gone
  });
});

// covers: REQ-KG-CONF-06
import { describe, it, expect } from "vitest";
import { fixPlanFor, fixPlan } from "./conflictFixPlan";
import type { ConflictFinding } from "./types";

const finding = (id: string): ConflictFinding => ({
  id, subject: "net_margin", scope: "pfl", category: "formula", severity: "high", axis: "mixed", tags: [], why: "",
  positions: [
    { id: "A", statement: "/ gross_revenue", heldBy: ["doc:fin"] },
    { id: "B", statement: "/ net_revenue", heldBy: ["run.py"] },
  ],
  participants: [
    { kind: "doc", ref: "doc:fin", quote: "/ gross_revenue", positionId: "A", span: "§3" },
    { kind: "code", ref: "run.py", quote: "/ net_revenue", positionId: "B" },
  ],
});

describe("fixPlanFor", () => {
  it("targets the dissenters (non-canonical participants), classified by fix type", () => {
    const plan = fixPlanFor(finding("cf-1"), "A")!; // A canonical → code participant (B) is the dissenter
    expect(plan.canonicalStatement).toBe("/ gross_revenue");
    expect(plan.targets).toEqual([{ ref: "run.py", kind: "code", via: "code-tdd", quote: "/ net_revenue", span: undefined }]);
  });
  it("routes a dissenting doc to a doc-edit and a dissenting code to a code-tdd", () => {
    const plan = fixPlanFor(finding("cf-1"), "B")!; // B canonical → doc participant (A) is the dissenter
    expect(plan.targets).toEqual([{ ref: "doc:fin", kind: "doc", via: "doc-edit", quote: "/ gross_revenue", span: "§3" }]);
  });
  it("returns null when the canonical position id does not exist", () => {
    expect(fixPlanFor(finding("cf-1"), "Z")).toBeNull();
  });
});

describe("fixPlan", () => {
  it("builds plans only for resolved decisions that name a canonical position", () => {
    const findings = [finding("cf-1"), finding("cf-2"), finding("cf-3")];
    const decisions = {
      "cf-1": { status: "resolved" as const, positionId: "A" },
      "cf-2": { status: "dismissed" as const },
      "cf-3": { status: "resolved" as const }, // no positionId → skipped
    };
    const plans = fixPlan(findings, decisions);
