// REQ-1 (founding design §7): the committed fixture projects — one-repo and multi-repo — build to
// their committed expected graphs, byte-identical, on any machine, with no access to any private
// codebase.
//
// This is REQ-0's permanent successor (§12.1, CEO 2026-07-17). REQ-0 proved the PORT against a
// private tree and retired; these fixtures are the standing, CI-runnable proof that "generic" is
// real. They test the assumption rather than the spelling (§12.9): a tool that silently hardcodes a
// layout builds the wrong fixture graph whether or not it ever names a project.
//
// Byte-identity is over the NORMALIZED graph — check.ts's normalizeForCompare, the same comparator
// `check` gates freshness with — because git created/updated dates belong to this repo's history,
// not to the fixture's content. The build itself injects an inert GitRunner so the expected graphs
// are reproducible on a machine with no git at all.
//
// To regenerate after a DELIBERATE fixture or tool-behaviour change:
//   npx tsx scripts/fixture-expected.mts
// and review the diff — the expected graph is a committed claim, not a cache.
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { buildGraph } from "./discover";
import { loadConfig } from "./config";
import { graphsMatch, normalizeForCompare } from "./check";
import type { GitRunner } from "./gitDates";
import type { Graph } from "./types";

const FIXTURES = join(__dirname, "..", "fixtures");
const PINNED = "2000-01-01T00:00:00.000Z";
/** Git reports nothing: no dates get stamped, so the graph is machine- and history-independent. */
const NO_GIT: GitRunner = async () => null;

async function build(fixture: string): Promise<Graph> {
  const root = join(FIXTURES, fixture);
  const config = await loadConfig(root);
  return buildGraph(root, PINNED, config, NO_GIT);
}

async function expected(fixture: string): Promise<{ text: string; graph: Graph }> {
  const text = (await readFile(join(FIXTURES, `${fixture}.expected.json`), "utf8")).trim();
  return { text, graph: JSON.parse(text) as Graph };
}

describe("REQ-1 — one-repo fixture", () => {
  it("builds byte-identically to its committed expected graph", async () => {
    const fresh = await build("one-repo");
    const exp = await expected("one-repo");
    expect(JSON.stringify(normalizeForCompare(fresh))).toBe(exp.text);
    expect(graphsMatch(exp.graph, fresh)).toBe(true);
  });

  it("produces the graph the fixture was designed to produce", async () => {
    const g = await build("one-repo");
    const ids = new Set(g.nodes.map((n) => n.id));

    // The degenerate topology: one repo owning the root, everything namespaced `main:`.
    expect(ids).toContain("main:checkout-spec"); // the doc
    expect(ids).toContain("main:checkout"); // the feature
    expect(ids).toContain("main:checkout-happy-path"); // the e2e case
    expect(ids).toContain("main:src/checkout.test.ts"); // the unit test, repo-relative bare id
    expect(ids).toContain("main:claude"); // CLAUDE.md as an instruction node
    expect(ids).toContain("REQ-FX-1"); // requirement ids are never namespaced
    expect(ids).toContain("REQ-FX-2");
    expect(ids).toContain("REQ-FX-3");

    // The case's bare `features: [checkout]` tag resolves to the namespaced feature.
    expect(g.edges).toContainEqual(
      expect.objectContaining({ from: "main:checkout-happy-path", to: "main:checkout", type: "tags" }),
    );
    // The unit test's tag edge is DERIVED from the feature's path globs, not authored.
    expect(g.edges).toContainEqual(
      expect.objectContaining({ from: "main:src/checkout.test.ts", to: "main:checkout", type: "tags", source: "derived" }),
    );

    // Three issues, each deliberate, each a distinct kind — pinning the issue machinery:
    // REQ-FX-2 has no covering test; the doc has an unproven requirement so the soft escape
    // hatch must NOT launder it; orphan.spec.ts has no case entry.
    expect(g.issues.map((i) => [i.kind, i.node ?? i.detail])).toEqual([
      ["uncovered-requirement", "REQ-FX-2"],
      ["untracked-e2e", "e2e/orphan.spec.ts — no linked case entry (verifies/covers/features required)"],
      ["unverified-doc", "main:checkout-spec"],
    ]);

    // REQ-FX-1 is proven by the case's `covers`; REQ-FX-3 by `provenBy` resolving to the unit
    // test — neither may appear as uncovered.
    const uncovered = g.issues.filter((i) => i.kind === "uncovered-requirement").map((i) => i.node);
    expect(uncovered).not.toContain("REQ-FX-1");
    expect(uncovered).not.toContain("REQ-FX-3");
  });
});

describe("REQ-1 — multi-repo fixture", () => {
  it("builds byte-identically to its committed expected graph", async () => {
    const fresh = await build("multi-repo");
    const exp = await expected("multi-repo");
    expect(JSON.stringify(normalizeForCompare(fresh))).toBe(exp.text);
    expect(graphsMatch(exp.graph, fresh)).toBe(true);
  });

  it("namespaces every node by its owning repo and resolves links across repos", async () => {
    const g = await build("multi-repo");
    const ids = new Set(g.nodes.map((n) => n.id));

    expect(ids).toContain("main:workspace-spec"); // root repo doc
    expect(ids).toContain("backend:api-spec"); // nested repo doc
    expect(ids).toContain("backend:tests/test_rates.py"); // pytest unit test, repo-relative bare id
    expect(ids).toContain("frontend:rates-widget"); // features registry lives in the frontend repo
    expect(ids).toContain("frontend:rates-api");
    expect(ids).toContain("frontend:rates-happy"); // e2e case
    expect(ids).toContain("frontend:fixture-notes"); // the deliberate orphan

    // A bare wikilink in the root doc resolves across the repo boundary.
    expect(g.edges).toContainEqual(
      expect.objectContaining({ from: "main:workspace-spec", to: "backend:api-spec", type: "references" }),
    );
    // A backend pytest file tags a feature registered in the frontend's registry.
    expect(g.edges).toContainEqual(
      expect.objectContaining({ from: "backend:tests/test_rates.py", to: "frontend:rates-api", type: "tags", source: "derived" }),
    );
    // The e2e case verifies the backend doc by bare slug, resolved cross-repo.
    expect(g.edges).toContainEqual(
      expect.objectContaining({ from: "frontend:rates-happy", to: "backend:api-spec", type: "verifies" }),
    );

    // REQ-FXB-1 is proven (covers edge + provenBy → the pytest node) — never uncovered. And
    // api-spec's every requirement being proven means the soft escape hatch clears it of
    // unverified-doc… but it also has a direct `verifies` from the case, so both paths hold.
    expect(g.issues.filter((i) => i.kind === "uncovered-requirement")).toEqual([]);
    expect(g.issues.map((i) => i.node ?? "")).not.toContain("backend:api-spec");

    // The deliberate defects: a wikilink to a doc that does not exist, and an orphan doc.
    expect(g.issues).toContainEqual(
      expect.objectContaining({ kind: "broken-link", from: "main:workspace-spec", to: "missing-doc" }),
    );
    expect(g.issues).toContainEqual(expect.objectContaining({ kind: "orphan-doc", node: "frontend:fixture-notes" }));
  });
});

describe("REQ-1 — the committed expected graphs", () => {
  it("are stored already-normalized, so what is committed is exactly what is compared", async () => {
    for (const fixture of ["one-repo", "multi-repo"]) {
      const exp = await expected(fixture);
      expect(JSON.stringify(normalizeForCompare(exp.graph))).toBe(exp.text);
    }
  });
});

// covers: REQ-KG-CTX-01, REQ-KG-CONF-02
// The briefing's governed/grandfathered/halt verdicts, and the scan surface reaching code with no
// docs — both asserted end to end here, from outside, against a repo that is not this one.
import { describe, it, expect, beforeAll, afterAll } from "vitest";
import { execFile } from "node:child_process";
import { mkdtemp, mkdir, readFile, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { promisify } from "node:util";

/**
 * The plugin, exercised the way a stranger installs it: from OUTSIDE, against a repo that is not this
 * one, with `KG_REPO_ROOT` pointing elsewhere.
 *
 * Every unit test in this suite builds graphs in-process, which cannot catch the class of defect that
 * has actually shipped here — entrypoints resolving paths from the tool's own directory, a config
 * error surfacing as a raw stack trace, the freeze sweeping the tool's own artifacts into the
 * baseline. All three were found by running this sequence by hand; this is that walkthrough, kept.
 *
 * The fixture is deliberately a repo with NO docs, NO tests and NO config — the founding design's
 * customer (§1), and the state in which every other test's assumptions are least true.
 */
const run = promisify(execFile);
const TOOL = join(__dirname, "..");

let repo: string;
/** Spawned from the TOOL's own directory, so a path resolved from `__dirname` would find the wrong tree. */
const kg = (script: string, ...args: string[]) =>
  run("npx", ["tsx", join(TOOL, "src", script), ...args], { cwd: TOOL, env: { ...process.env, KG_REPO_ROOT: repo } });

beforeAll(async () => {
  repo = await mkdtemp(join(tmpdir(), "kg-fresh-install-"));
  await mkdir(join(repo, "src"), { recursive: true });
  await mkdir(join(repo, "lib"), { recursive: true });
  // The same rule implemented twice, disagreeing on both the rate and the basis. No doc says which is
  // right — that is the point, and it is where a bare repo's first requirement comes from.
  await writeFile(join(repo, "src", "pricing.ts"),
    "export const TAX_RATE = 0.2;\nexport function applyTax(o: any) { return o.subtotal * (1 + TAX_RATE); }\n");
  await writeFile(join(repo, "lib", "invoice.ts"),
    "export const TAX_RATE = 0.15;\nexport function applyTax(o: any) { return (o.subtotal - o.discount) * (1 + TAX_RATE); }\n");
  await writeFile(join(repo, "src", "mailer.ts"), "export function sendReceipt(to: string) { return to; }\n");
});
afterAll(async () => { await rm(repo, { recursive: true, force: true }); });

describe("a fresh install, on somebody else's repo", () => {
  // The tool must never guess a layout — guessing wrong emits a complete, confident, wrong graph. But
  // the refusal has to READ like an instruction, not like a crash: this is kg-init step 2, so it is
  // the first thing a new user sees on the likeliest mistake.
  it("refuses to build without a config, and says what to do about it", async () => {
    const err: any = await kg("build.ts").catch((e) => e);
    expect(err.code, "build must fail without a config, not guess one").not.toBe(0);
    expect(err.stderr).toMatch(/kg\.config\.json/);
    expect(err.stderr).toMatch(/kg-init/);
    // The message is useless if it arrives wrapped in a stack trace nobody reads to the end of.
    expect(err.stderr).not.toMatch(/at .*\(.*:\d+:\d+\)/);
  });

  it("builds an honestly empty graph once the topology is declared", async () => {
    await writeFile(join(repo, "kg.config.json"), JSON.stringify({
      repos: [{ name: "main", subdir: "" }], e2eDir: "e2e", artifactDir: "knowledge-graph", unitTestGlobs: [],
    }));
    const { stdout } = await kg("build.ts");
    // A repo with no docs and no registered tests HAS no nodes. Thin is the honest answer here.
    expect(stdout).toMatch(/kg: 0 nodes/);
  });

  it("freezes only the project's own files, never the artifacts it just generated", async () => {
    await kg("ungovernedBaselineCli.ts");
    const frozen: string[] = JSON.parse(await readFile(join(repo, "knowledge-graph", "ungoverned-baseline.json"), "utf8"));
    expect(frozen).toContain("src/pricing.ts");
    expect(frozen).toContain("lib/invoice.ts");
    // The graph, viewer, report and digest are rebuilt every run; freezing them records the tool's own
    // output as excused code and pads the count with churn.
    expect(frozen.filter((p) => p.startsWith("knowledge-graph/"))).toEqual([]);
  });

  it("grandfathers what already existed and halts on what comes next", async () => {
    const existing = await kg("agentContextCli.ts", "src/pricing.ts");
    expect(existing.stdout).toMatch(/grandfathered/i);
    const fresh = await kg("agentContextCli.ts", "src/checkout.ts");
    expect(fresh.stdout).toMatch(/STOP/);
  });

  // The differentiated claim: contradictions found with no docs at all, which is the only way a repo
  // in this state gets a first requirement.
  it("finds a code-vs-code contradiction with no docs in the repo", async () => {
    const out = JSON.parse((await kg("scanContext.ts")).stdout);
    const pair = out.items.find((i: any) => i.pair.kind === "code-code");
    expect(pair, "a bare repo must still yield a candidate surface").toBeTruthy();
    expect([pair.a.ref, pair.b.ref].sort()).toEqual(["lib/invoice.ts", "src/pricing.ts"]);
    expect(pair.pair.sharedSymbols).toContain("TAX_RATE");
    // Precision is the product: a file sharing no declaration is never dragged in.
    expect(out.items.flatMap((i: any) => [i.a.ref, i.b.ref])).not.toContain("src/mailer.ts");
  });

  // The accretion step — the whole point of the previous one. Writing the adjudication down as a
  // requirement is what turns an ungoverned file into a governed one and shrinks the ratchet.
  it("governs the file once a requirement is written, and the baseline falls", async () => {
    await mkdir(join(repo, ".github", "system-design"), { recursive: true });
    await writeFile(join(repo, ".github", "system-design", "PRICING.md"),
      ["---", "slug: pricing", "title: Pricing", "domain: shop", "status: current", "entrypoint: true",
       "governs:", "  - src/pricing.ts", "  - lib/invoice.ts",
       "requirements:", "  - id: REQ-SHOP-01", "    text: Tax applies to the discounted total.", "---", "", "## Basis", ""].join("\n"));
    await kg("build.ts");

    const pack = await kg("agentContextCli.ts", "src/pricing.ts");
    expect(pack.stdout).toMatch(/## Governed by/);
    expect(pack.stdout).toMatch(/REQ-SHOP-01/);
    expect(pack.stdout).not.toMatch(/grandfathered/i);

    const { stdout } = await kg("ungovernedBaselineCli.ts", "--prune");
    expect(stdout).toMatch(/dropped 2 now-governed/);
  });
});

// covers: REQ-KG-04
import { describe, it, expect } from "vitest";
import { gateDecision } from "./gateDecision";

// gateDecision is the pure readiness-gate policy extracted out of ensureServers
// / the pre-run gate in serve.ts, so the tricky branching (nothing listening →
// let Playwright manage servers; something listening but never healthy → give
// up; still within the timeout → keep waiting) is unit-testable without a real
// HTTP server or real timers.
describe("gateDecision", () => {
  it("proceeds immediately when both servers are already up and healthy", () => {
    expect(gateDecision(true, true, true, true, 0, 60_000)).toBe("proceed");
  });

  it("proceeds when NOTHING is listening on either port (Playwright will manage servers itself)", () => {
    expect(gateDecision(false, false, false, false, 0, 60_000)).toBe("proceed");
  });

  it("proceeds when nothing listens on one side and the other side is fully healthy (still nobody wedged)", () => {
    // FE not up at all, BE fully healthy — FE will be Playwright-managed.
    expect(gateDecision(false, false, true, true, 0, 60_000)).toBe("proceed");
  });

  it("waits when a port is listening but not yet returning .ok, and we're inside the timeout window", () => {
    // FE listening (compiling) but not healthy yet; BE fine.
    expect(gateDecision(true, false, true, true, 5_000, 60_000)).toBe("wait");
  });

  it("waits when neither has confirmed ok yet but at least one is listening, within the window", () => {
    expect(gateDecision(true, false, true, false, 100, 60_000)).toBe("wait");
  });

  it("gives up (serverNotReady) when a listening-but-unhealthy port exceeds the timeout", () => {
    expect(gateDecision(true, false, true, true, 60_001, 60_000)).toBe("serverNotReady");
  });

  it("gives up exactly at the timeout boundary (waitedMs === timeoutMs counts as elapsed)", () => {
    expect(gateDecision(true, false, true, true, 60_000, 60_000)).toBe("serverNotReady");
  });

  it("proceeds once the previously-wedged listener turns healthy before the timeout", () => {
    expect(gateDecision(true, true, true, true, 55_000, 60_000)).toBe("proceed");
  });

  it("waits (not serverNotReady) when backend is the wedged one and frontend is healthy", () => {
    expect(gateDecision(true, true, true, false, 1_000, 60_000)).toBe("wait");
  });

  it("gives up when backend is the one that stays wedged past the timeout", () => {
    expect(gateDecision(true, true, true, false, 60_500, 60_000)).toBe("serverNotReady");
  });

  it("respects a custom timeout (KG_READY_TIMEOUT override)", () => {
    expect(gateDecision(true, false, true, true, 4_999, 5_000)).toBe("wait");
    expect(gateDecision(true, false, true, true, 5_000, 5_000)).toBe("serverNotReady");
  });
});

import { describe, it, expect } from "vitest";
import { REPOS, SOLO } from "./topology.fixture";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";
import { parseGitLog, docDates, type GitRunner } from "./gitDates";

// git log --format=%x00%aI --name-only emits, newest→oldest: a NUL then the ISO author date on one
// line, then the changed file paths one per line. parseGitLog collapses that to per-file created
// (oldest date seen) / updated (newest date seen), normalized to YYYY-MM-DD.
const NUL = "\x00";

describe("parseGitLog", () => {
  it("maps a single file in one commit with created == updated == that date", () => {
    const out = `${NUL}2026-07-10T12:00:00+08:00\ndocs/a.md\n`;
    const m = parseGitLog(out);
    expect(m.get("docs/a.md")).toEqual({ created: "2026-07-10", updated: "2026-07-10" });
    expect(m.size).toBe(1);
  });

  const multi = [
    `${NUL}2026-07-10T12:00:00+08:00`,
    "docs/a.md",
    "docs/b.md",
    "",
    `${NUL}2026-07-05T09:00:00+08:00`,
    "docs/a.md",
    "",
    `${NUL}2026-06-01T08:00:00+08:00`,
    "docs/a.md",
    "docs/c.md",
  ].join("\n");

  it("for a file across several commits, created = oldest and updated = newest (git emits newest→oldest)", () => {
    const m = parseGitLog(multi);
    expect(m.get("docs/a.md")).toEqual({ created: "2026-06-01", updated: "2026-07-10" });
  });

  it("tracks a file present in only some commits independently of the others", () => {
    const m = parseGitLog(multi);
    // b.md only in the newest commit; c.md only in the oldest commit
    expect(m.get("docs/b.md")).toEqual({ created: "2026-07-10", updated: "2026-07-10" });
    expect(m.get("docs/c.md")).toEqual({ created: "2026-06-01", updated: "2026-06-01" });
  });

  it("returns an empty map for empty output", () => {
    expect(parseGitLog("").size).toBe(0);
  });

  it("ignores blank lines, a malformed date header, and path lines with no date context", () => {
    const out = [
      "",                            // leading blank
      `${NUL}not-a-date`,            // malformed date header → no context set
      "orphan-before-any-date.md",   // path before any valid date → ignored
      `${NUL}2026-07-10T00:00:00Z`,  // valid header
      "",                            // blank between header and files
      "docs/a.md",
      "   ",                         // whitespace-only → ignored
    ].join("\n");
    const m = parseGitLog(out);
    expect(m.get("docs/a.md")).toEqual({ created: "2026-07-10", updated: "2026-07-10" });
    expect(m.has("orphan-before-any-date.md")).toBe(false);
    expect(m.size).toBe(1);
  });
});

describe("docDates — grouping, prefix strip/re-add, one process per repo (injected runner)", () => {
  it("runs one git process per repo group against the right root, strips the repo prefix for git, and re-adds it on the result keys", async () => {
    const calls: { cwd: string; relPaths: string[] }[] = [];
    const runner: GitRunner = async (cwd, relPaths) => {
      calls.push({ cwd, relPaths });
      if (cwd.endsWith("svc_backend"))
        return `${NUL}2026-07-10T00:00:00Z\n.github/system-design/foo.md\n\n${NUL}2026-03-03T00:00:00Z\n.github/memories/note.md\n`;
      if (cwd.endsWith("svc_frontend")) return `${NUL}2026-05-02T00:00:00Z\ne2e/cases/bar.cases.yaml\n`;
      return `${NUL}2026-01-01T00:00:00Z\nCLAUDE.md\n`; // main
    };
    const root = "/repo/root";
    const paths = [
      "svc_backend/.github/system-design/foo.md",
      "svc_backend/.github/memories/note.md",
      "svc_frontend/e2e/cases/bar.cases.yaml",
      "CLAUDE.md",
    ];
    const m = await docDates(root, paths, REPOS, runner);

    // exactly one process per distinct repo (backend, frontend, main)
    expect(calls.length).toBe(3);

    const backendCall = calls.find((c) => c.cwd === join(root, "svc_backend"))!;
    expect(backendCall).toBeDefined();
    // repo prefix stripped; runner receives the repo-relative paths as an argv-ready array
    expect(backendCall.relPaths).toEqual([".github/system-design/foo.md", ".github/memories/note.md"]);

    expect(calls.find((c) => c.cwd === join(root, "svc_frontend"))?.relPaths).toEqual(["e2e/cases/bar.cases.yaml"]);
    expect(calls.find((c) => c.cwd === root)?.relPaths).toEqual(["CLAUDE.md"]); // main uses repoRoot itself

    // keys are the ORIGINAL input paths (prefix re-added)
    expect(m.get("svc_backend/.github/system-design/foo.md")).toEqual({ created: "2026-07-10", updated: "2026-07-10" });
    expect(m.get("svc_backend/.github/memories/note.md")).toEqual({ created: "2026-03-03", updated: "2026-03-03" });
    expect(m.get("svc_frontend/e2e/cases/bar.cases.yaml")).toEqual({ created: "2026-05-02", updated: "2026-05-02" });
    expect(m.get("CLAUDE.md")).toEqual({ created: "2026-01-01", updated: "2026-01-01" });
  });

  it("tolerates a per-repo git failure (runner returns null) — that group contributes nothing, others still resolve", async () => {
    const runner: GitRunner = async (cwd) => {
      if (cwd.endsWith("svc_backend")) return null; // non-git dir / git exited non-zero
      return `${NUL}2026-01-01T00:00:00Z\nCLAUDE.md\n`;
    };
    const m = await docDates("/root", ["svc_backend/x/y.md", "CLAUDE.md"], REPOS, runner);
    expect(m.has("svc_backend/x/y.md")).toBe(false);
    expect(m.get("CLAUDE.md")).toEqual({ created: "2026-01-01", updated: "2026-01-01" });
  });

  it("tolerates a runner that throws (missing git binary) — caught and skipped, other groups resolve", async () => {
    const runner: GitRunner = async (cwd) => {
      if (cwd.endsWith("svc_frontend")) throw new Error("spawn git ENOENT");
      return `${NUL}2026-02-02T00:00:00Z\nCLAUDE.md\n`;
    };
    const m = await docDates("/root", ["svc_frontend/a.md", "CLAUDE.md"], REPOS, runner);
    expect(m.has("svc_frontend/a.md")).toBe(false);
    expect(m.get("CLAUDE.md")).toEqual({ created: "2026-02-02", updated: "2026-02-02" });
  });

  it("returns an empty map and never spawns git when given no paths", async () => {
    let called = 0;
    const runner: GitRunner = async () => {
      called++;
      return "";
    };
    const m = await docDates("/root", [], REPOS, runner);
    expect(m.size).toBe(0);
    expect(called).toBe(0);
  });
});

// Regression / smoke test for the real spawn path. The original defaultGitRunner used
// `git log ... --pathspec-from-file=- --pathspec-file-nul`, which git 2.32 rejects
// (`fatal: unrecognized argument: --pathspec-from-file=-`) → every process exited non-zero →
// docDates returned nothing for every node. This test exercises the DEFAULT runner (no injection)
// against a file known to be tracked in THIS repo, so a broken real spawn can never pass again.
// This repo IS the workspace under test — a single-repo project, which is the degenerate topology and
// the one worth smoke-testing against real git. It used to walk `join(here, "..", "..", "..")` to
// reach a workspace three levels up, which was true only of the in-tree copy: after the port that path
// left the git repo entirely, `gitUsable` went false, and this guard SILENTLY SKIPPED. A regression
// test that stops running is worse than one that fails, because nothing says so (§10.2's lesson).
const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, "..");
function gitUsable(cwd: string): boolean {
  try {
    const r = spawnSync("git", ["-C", cwd, "rev-parse", "--is-inside-work-tree"], { encoding: "utf8" });
    return r.status === 0 && String(r.stdout).trim() === "true";
  } catch {
    return false;
  }
}
const REAL_GIT = gitUsable(repoRoot);

describe("docDates — real git (default runner, no injection)", () => {
  it.skipIf(!REAL_GIT)("dates a tracked file via a real git spawn (created <= updated, both YYYY-MM-DD)", async () => {
    const tracked = "package.json"; // tracked in this repo, at its root, so cwd = repoRoot
    const m = await docDates(repoRoot, [tracked], SOLO); // DEFAULT runner — real `git log`
    const d = m.get(tracked);
    expect(d).toBeDefined();
    expect(d!.created).toMatch(/^\d{4}-\d{2}-\d{2}$/);
    expect(d!.updated).toMatch(/^\d{4}-\d{2}-\d{2}$/);
    expect(d!.created! <= d!.updated!).toBe(true); // oldest commit no later than newest
  });
});

// covers: REQ-KG-CTX-01
import { describe, it, expect } from "vitest";
import { editedPathFrom, hookDecision } from "./hookBriefing";
import type { ContextPack } from "./agentContext";

/**
 * The hook contract, which this plugin got wrong in both directions from the day it shipped.
 *
 * `hooks.json` passed `"${TOOL_INPUT_FILE_PATH}"` — not a substitution Claude Code performs. It
 * expanded to an empty string, the CLI printed its usage line and exited 2, and `|| true` swallowed
 * that. And even had the path arrived, a PreToolUse hook's plain stdout is DISCARDED: the model sees
 * `permissionDecisionReason`, nothing else. So the briefing — founding design §5's "gold", the thing
 * that makes the graph get consulted at all — never reached a single session.
 *
 * Both halves are asserted here because fixing either one alone still yields silence.
 */

const pack = (over: Partial<ContextPack> = {}): ContextPack => ({
  path: "src/pay.ts",
  governedBy: [],
  features: [],
  requirements: [],
  tests: [],
  conflicts: [],
  halt: false,
  grandfathered: false,
  ...over,
});

describe("editedPathFrom — the path arrives as JSON on stdin, never as an env var", () => {
  it("reads file_path for Edit and Write", () => {
    expect(editedPathFrom(JSON.stringify({ tool_name: "Edit", tool_input: { file_path: "/repo/src/a.ts" } })))
      .toBe("/repo/src/a.ts");
    expect(editedPathFrom(JSON.stringify({ tool_name: "Write", tool_input: { file_path: "/repo/src/b.ts" } })))
      .toBe("/repo/src/b.ts");
  });

  // NotebookEdit names its target differently. Missing this means notebooks silently get no briefing
  // while every other edit gets one — the worst kind of gap, because it looks like it works.
  it("reads notebook_path for NotebookEdit", () => {
    expect(editedPathFrom(JSON.stringify({ tool_name: "NotebookEdit", tool_input: { notebook_path: "/repo/n.ipynb" } })))
      .toBe("/repo/n.ipynb");
  });

  it("returns null rather than guessing when there is no path", () => {
    expect(editedPathFrom(JSON.stringify({ tool_name: "Edit", tool_input: {} }))).toBeNull();
    expect(editedPathFrom("not json")).toBeNull();
    expect(editedPathFrom("")).toBeNull();
  });
});

describe("hookDecision — only additionalContext reaches the model", () => {
  it("emits the shape a PreToolUse hook must emit", () => {
    const out = hookDecision(pack({ governedBy: [{ id: "main:spec", title: "Spec" }] }));
    expect(out.hookSpecificOutput.hookEventName).toBe("PreToolUse");
    expect(out.hookSpecificOutput.permissionDecision).toBe("allow");
  });

  /**
   * THE FIELD THAT ACTUALLY INJECTS. A PreToolUse hook returning only a permission decision is
   * classified by Claude Code as "harness-only — no model context cost", and the briefing reaches
   * nobody: verified against a live install, where `plugin details` said exactly that and a Write
   * produced no briefing at all. `additionalContext` is the field that puts text beside the tool
   * result. `permissionDecisionReason` is kept as well — it explains the decision — but on its own it
   * was the third way this hook found to be silent.
   */
  it("puts the briefing in additionalContext, which is what reaches the model", () => {
    const out = hookDecision(pack({ halt: true, reason: "Nothing governs this path" }));
    expect(out.hookSpecificOutput.additionalContext).toMatch(/STOP/);
  });

  // The whole point. A decision with no context is a hook that allows the edit and says nothing —
  // exactly the silence this replaces.
  it("carries the whole briefing, not a summary of it", () => {
    const out = hookDecision(pack({
      governedBy: [{ id: "main:spec", title: "Checkout spec", path: ".github/system-design/C.md" }],
      requirements: [{ id: "REQ-1", text: "A total sums its lines.", provenBy: [], draft: false }],
    }));
    const reason = out.hookSpecificOutput.additionalContext;
    expect(reason).toMatch(/Checkout spec/);
    expect(reason).toMatch(/REQ-1/);
    expect(reason).toMatch(/NO COVERING TEST/);
  });

  // permissionDecisionReason explains the DECISION and is short; the briefing itself is the context.
  // Conflating them is what made this silent — a long reason on an `allow` is read by nobody.
  it("keeps the decision's reason short and distinct from the briefing", () => {
    const out = hookDecision(pack({ halt: true, reason: "Nothing governs this path" }));
    expect(out.hookSpecificOutput.permissionDecisionReason).toMatch(/no governing requirement/i);
    expect(out.hookSpecificOutput.permissionDecisionReason.length).toBeLessThan(120);
  });

  // Non-blocking is the documented design (hooks.json): a project that has not been governed yet must
  // never be locked out of its own repo on install day. The halt is an instruction, not a veto.
  it("never denies the edit, even on a halt", () => {
    expect(hookDecision(pack({ halt: true, reason: "x" })).hookSpecificOutput.permissionDecision).toBe("allow");
  });
});

