// covers: REQ-KG-SUB-06
import { describe, it, expect } from "vitest";
import { pathToFileURL } from "node:url";
import { realpathSync } from "node:fs";
import { mkdtemp, mkdir, symlink, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { isMain } from "./isMain";

/**
 * REQ-KG-SUB-06 — the canonical answer to "am I the process entrypoint?", chosen by the CEO on
 * 2026-07-26 as position B of conflict cf-4b6d6187fc.
 *
 * Six CLI modules answered this three ways. The two cases below are exactly where the three
 * disagreed, so each is a real defect in one of the losing positions rather than a hypothetical:
 *
 *   - a path needing URL encoding (a space) — position C string-concatenated `file://` onto argv[1]
 *     and produced an unencoded URL that never matched, then leaned on a filename-suffix fallback to
 *     get the right answer for the wrong reason;
 *   - an absent argv[1] — position A called `pathToFileURL(undefined)`, which throws.
 */
describe("isMain — one answer, in one place", () => {
  it("is true when the module is the invoked script", () => {
    const url = pathToFileURL("/repo/src/build.ts").href;
    expect(isMain(url, "/repo/src/build.ts")).toBe(true);
  });

  it("is false when some other script was invoked", () => {
    const url = pathToFileURL("/repo/src/build.ts").href;
    expect(isMain(url, "/repo/src/serve.ts")).toBe(false);
  });

  // Position C's PRIMARY comparison is wrong here — `file://` + "/repo/my project/…" yields a raw
  // space that never equals the encoded import.meta.url. Verified by running C against this test: it
  // still passes, because the filename fallback catches what the comparison missed. So this pins the
  // right answer without discriminating C from B; the suffix case below is what actually catches C.
  it("is true for a path that needs URL encoding", () => {
    const path = "/repo/my project/src/build.ts";
    expect(isMain(pathToFileURL(path).href, path)).toBe(true);
  });

  // Position A's defect: pathToFileURL(undefined) throws, taking the whole process down at import
  // time — for a module that was only ever imported, never run.
  it("is false, and does not throw, when no script was invoked", () => {
    const url = pathToFileURL("/repo/src/build.ts").href;
    expect(() => isMain(url, undefined)).not.toThrow();
    expect(isMain(url, undefined)).toBe(false);
  });

  // The suffix fallback position C used: any invoked script whose name merely ENDS WITH this
  // module's filename claimed to be it. `run-build.ts` is not `build.ts`.
  it("is false for a different script whose filename merely ends with this one's", () => {
    const url = pathToFileURL("/repo/src/build.ts").href;
    expect(isMain(url, "/repo/src/run-build.ts")).toBe(false);
  });

  /**
   * The defect the approved position B still had, found by running a bundled entrypoint out of a
   * macOS temp dir: `import.meta.url` is ALWAYS the resolved real path, while `process.argv[1]` is
   * whatever the caller typed. Invoke a script through any symlink — /tmp on macOS, a symlinked
   * checkout, a pnpm store — and the two never match, so the module decides it is not the entrypoint
   * and every CLI silently does nothing. Same silence the whole conflict was about.
   */
  it("is true when the script was invoked through a symlink", async () => {
    const dir = await mkdtemp(join(tmpdir(), "kg-ismain-link-"));
    try {
      const real = join(dir, "real");
      const link = join(dir, "link");
      await mkdir(real, { recursive: true });
      await writeFile(join(real, "cli.mjs"), "");
      await symlink(real, link, "dir");
      // What node ACTUALLY reports for a run via the link: `import.meta.url` fully resolved (verified
      // by probe — a script under macOS /tmp reports /private/tmp), and argv[1] left as typed. The
      // realpath here is the fixture being accurate, not the assertion being softened: without it the
      // test also has to survive tmpdir() itself being a symlink, which is a different bug.
      const moduleUrl = pathToFileURL(realpathSync(join(real, "cli.mjs"))).href;
      expect(isMain(moduleUrl, join(link, "cli.mjs"))).toBe(true);
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
  });
});

// R2-B integration pin: fabricated Playwright JSON → parsePlaywrightJson → per-entry
// commit stamping (the same composition syncResults.ts performs) → mergeResults into a
// pre-existing results file whose entries PREDATE the error/commit fields → applyResults
// onto test nodes → renderViewer template data. Proves the whole last-run pipeline without
// re-running any real e2e (today's kg-test-results.json entries lack `error`/`commit` by
// design — they predate the schema and must render honestly, not be backfilled).
import { describe, it, expect } from "vitest";
import { parsePlaywrightJson } from "./parsePlaywrightReport";
import { mergeResults, normalizeResults, type ResultsFileV2 } from "./resultsFile";
import { applyResults } from "./parseResults";
import { renderViewer } from "./viewer";
import { repoDirNames } from "./config";
import { CONFIG } from "./topology.fixture";

const NOW = "2026-07-06T09:00:00.000Z";
const COMMIT = "9f8e7d6";

// The workspace this fabricated report was supposedly produced in. Derived through the real
// repoDirNames() rather than hand-listed, because that is exactly what syncResults.ts passes — and an
// integration pin that skips the derivation stops pinning the composition it claims to.
const WORKSPACE = "/Users/ching/workspace/ws_root";
const REPO_DIRS = repoDirNames(CONFIG, WORKSPACE);

const playwrightReport = JSON.stringify({
  suites: [{ title: "underwrite.spec.ts", specs: [
    {
      title: "UW-8 reverse yield", ok: false,
      tests: [{ results: [
        { status: "failed", errors: [{ message: "\u001b[31mError: expect(locator).toBeVisible() failed\u001b[39m\n\nLocator: getByTestId('npi-yield-trend')\n    at C:\\Users\\ching\\workspace\\ws_root\\svc_frontend\\e2e\\underwrite.spec.ts:88:3" }] },
        { status: "failed", errors: [{ message: "retry error — must not win" }] },
      ] }],
    },
    { title: "UW-9 auto landing", ok: true, tests: [{ results: [{ status: "passed" }] }] },
  ] }],
});

// A pre-R2B results file: entries have status/attempts/at but NO error/commit.
const existingFile = JSON.stringify({
  generatedAt: "2026-07-05T12:00:00.000Z", commit: "a0f73d76",
  results: { "uw-7": { status: "fail", attempts: 2, at: "2026-07-05T12:00:00.000Z" } },
});

describe("last-run pipeline (fabricated report → node → viewer data)", () => {
  const titles = new Map([["UW-8 reverse yield", "uw-8"], ["UW-9 auto landing", "uw-9"]]);
  const parsed = parsePlaywrightJson(playwrightReport, titles, REPO_DIRS);
  // Same shape syncResults.ts builds: per-entry `at` + per-entry `commit`.
  const incoming: ResultsFileV2 = {
    generatedAt: NOW, commit: COMMIT,
    results: Object.fromEntries(Object.entries(parsed).map(([id, r]) => [id, { ...r, at: NOW, commit: COMMIT }])),
  };
  const merged = mergeResults(normalizeResults(existingFile), incoming, true);
  const mergedJson = JSON.stringify(merged);

  const graph = {
    generatedAt: "T",
    nodes: [
      { id: "frontend:uw-7", type: "test", title: "UW-7", status: "todo", kind: "e2e" },
      { id: "frontend:uw-8", type: "test", title: "UW-8", status: "todo", kind: "e2e" },
      { id: "frontend:uw-9", type: "test", title: "UW-9", status: "todo", kind: "e2e" },
      { id: "frontend:uw-99", type: "test", title: "UW-99", status: "todo", kind: "e2e" },
    ],
    edges: [], issues: [],
  } as any;
  const g = applyResults(graph, mergedJson);
  const node = (id: string) => g.nodes.find((n: any) => n.id === id) as any;

  it("failed case: node carries status/attempts/runAt/lastError/runCommit, cleaned and truncated", () => {
    const n = node("frontend:uw-8");
    expect(n.status).toBe("fail");
    expect(n.attempts).toBe(2);
    expect(n.runAt).toBe(NOW);
    expect(n.runCommit).toBe(COMMIT);
    expect(n.lastError).toContain("Error: expect(locator).toBeVisible() failed");
    expect(n.lastError).not.toContain("\u001b");           // ANSI stripped
    expect(n.lastError).not.toMatch(/[A-Za-z]:\\Users/);   // no absolute-path leakage
    expect(n.lastError).not.toContain("retry error");      // first attempt's message wins
  });

  it("passing case: run info stamped, but never an error", () => {
    const n = node("frontend:uw-9");
    expect(n.status).toBe("pass");
    expect(n.runCommit).toBe(COMMIT);
    expect(n.lastError).toBeUndefined();
  });

  it("pre-R2B entry survives the scoped merge and stamps WITHOUT invented error/commit", () => {
    const n = node("frontend:uw-7");
    expect(n.status).toBe("fail");
    expect(n.runAt).toBe("2026-07-05T12:00:00.000Z");
    expect(n.lastError).toBeUndefined();
    expect(n.runCommit).toBeUndefined();
  });

  it("never-run case keeps its authored status and no run fields", () => {
    const n = node("frontend:uw-99");
    expect(n.status).toBe("todo");
    expect(n.runAt).toBeUndefined();
  });

  it("viewer data blob carries lastError/runCommit for the template to render", () => {
    const template = `<html><script>var KG=/*__KG_DATA__*/{nodes:[],edges:[],issues:[]}/*__KG_END__*/;</script></html>`;
    const out = renderViewer(g, template);
    const m = out.match(/var KG=(\{[\s\S]*\});/);
    expect(m).not.toBeNull();
    const kg = JSON.parse(m![1]);
    const uw8 = kg.nodes.find((n: any) => n.id === "frontend:uw-8");
    expect(uw8.lastError).toContain("expect(locator).toBeVisible() failed");
    expect(uw8.runCommit).toBe(COMMIT);
    // Determinism constraint: the generated HTML embeds only ISO strings — no
    // computed relative times may leak into build output (browser computes those).
    expect(uw8.runAt).toBe(NOW);
  });
});

// covers: REQ-KG-SERVE-01
import { describe, it, expect, vi } from "vitest";
import { EventEmitter } from "node:events";
import { LiveHub, type SseClient } from "./liveHub";

// A fake SSE client — the minimal ServerResponse surface the hub uses (write + "close" event).
// It records every SSE frame written so tests can assert on the exact event stream, and it
// exposes emitClose() to simulate a browser tab / EventSource disconnecting.
function makeClient(): SseClient & { frames: string[]; emitClose: () => void } {
  const ee = new EventEmitter();
  const frames: string[] = [];
  const client = {
    write(s: string) {
      frames.push(s);
      return true;
    },
    on(event: string, cb: () => void) {
      ee.on(event, cb);
      return client;
    },
    frames,
    emitClose() {
      ee.emit("close");
    },
  };
  return client as unknown as SseClient & { frames: string[]; emitClose: () => void };
}

describe("LiveHub", () => {
  it("sends an initial `hello` event to a new subscriber", () => {
    const hub = new LiveHub();
    const c = makeClient();
    hub.subscribe(c);
    expect(c.frames.join("")).toContain("event: hello");
    hub.dispose();
  });

  it("tracks connected clients in its size, and drops one on its `close` event", () => {
    const hub = new LiveHub();
    const a = makeClient();
    const b = makeClient();
    hub.subscribe(a);
    hub.subscribe(b);
    expect(hub.size).toBe(2);
    a.emitClose();
    expect(hub.size).toBe(1);
    b.emitClose();
    expect(hub.size).toBe(0);
    hub.dispose();
  });

  it("unsubscribe (returned by subscribe) also removes the client", () => {
    const hub = new LiveHub();
    const a = makeClient();
    const off = hub.subscribe(a);
    expect(hub.size).toBe(1);
    off();
    expect(hub.size).toBe(0);
    hub.dispose();
  });

  it("debounces a burst of notify() calls into a single graph-updated broadcast", () => {
    vi.useFakeTimers();
    try {
      const hub = new LiveHub({ debounceMs: 300 });
      const c = makeClient();
      hub.subscribe(c);
      c.frames.length = 0; // ignore the hello frame

      hub.notify();
      hub.notify();
      hub.notify(); // a mid-write burst — 3 fs events for one logical rebuild

      // Nothing pushed until the quiet window elapses.
      expect(c.frames.join("")).not.toContain("graph-updated");
      vi.advanceTimersByTime(299);
      expect(c.frames.join("")).not.toContain("graph-updated");
      vi.advanceTimersByTime(1);

      const out = c.frames.join("");
      const matches = out.match(/event: graph-updated/g) || [];
      expect(matches.length).toBe(1); // coalesced to exactly ONE push
    } finally {
      vi.useRealTimers();
    }
  });

  it("broadcasts graph-updated to every connected client", () => {
    vi.useFakeTimers();
    try {
      const hub = new LiveHub({ debounceMs: 100 });
      const a = makeClient();
      const b = makeClient();
      hub.subscribe(a);
      hub.subscribe(b);
      a.frames.length = 0;
      b.frames.length = 0;
      hub.notify();
      vi.advanceTimersByTime(100);
      expect(a.frames.join("")).toContain("event: graph-updated");
      expect(b.frames.join("")).toContain("event: graph-updated");
    } finally {
      vi.useRealTimers();
    }
  });

  it("does not broadcast to a client that already disconnected", () => {
    vi.useFakeTimers();
    try {
      const hub = new LiveHub({ debounceMs: 100 });
      const a = makeClient();
      const b = makeClient();
      hub.subscribe(a);
      hub.subscribe(b);
      a.frames.length = 0;
      b.frames.length = 0;
      a.emitClose(); // a leaves before the debounced push fires
      hub.notify();
      vi.advanceTimersByTime(100);
      expect(a.frames.join("")).not.toContain("event: graph-updated");
      expect(b.frames.join("")).toContain("event: graph-updated");
    } finally {
      vi.useRealTimers();
    }
  });

  it("sends periodic keepalive comments to connected clients", () => {
    vi.useFakeTimers();
    try {
      const hub = new LiveHub({ keepaliveMs: 25000 });
      const c = makeClient();
      hub.subscribe(c);
      c.frames.length = 0;
      vi.advanceTimersByTime(25000);
      expect(c.frames.join("")).toContain(": keepalive");
    } finally {
      vi.useRealTimers();
    }
  });

  it("dispose() clears timers and empties the client set", () => {
    vi.useFakeTimers();
    try {
      const hub = new LiveHub({ debounceMs: 100 });
      const c = makeClient();
      hub.subscribe(c);
      hub.notify();
      hub.dispose();
      expect(hub.size).toBe(0);
      c.frames.length = 0;
      // A pending debounced push must not fire after dispose.
      vi.advanceTimersByTime(1000);
      expect(c.frames.join("")).not.toContain("graph-updated");
    } finally {
      vi.useRealTimers();
    }
  });

  it("a write that throws (dead socket) is swallowed and drops that client", () => {
    vi.useFakeTimers();
    try {
      const hub = new LiveHub({ debounceMs: 100 });
      const good = makeClient();
      const bad = makeClient();
      // bad.write throws as if the socket were already torn down.
      (bad as unknown as { write: () => boolean }).write = () => {
        throw new Error("EPIPE");
      };
      hub.subscribe(good);
      hub.subscribe(bad);
      good.frames.length = 0;
      hub.notify();
      // Must not throw even though one client's write blows up.
      expect(() => vi.advanceTimersByTime(100)).not.toThrow();
      expect(good.frames.join("")).toContain("event: graph-updated");
      expect(hub.size).toBe(1); // the bad client was evicted
    } finally {
      vi.useRealTimers();
    }
  });
});

