});

// reviewedAt is the frontmatter `last_reviewed` value normalized to YYYY-MM-DD. gray-matter's
// YAML engine hands back a JS Date for a bare `last_reviewed: 2026-07-01` timestamp and a plain
// string for a quoted `"2026-07-01"` — parseDoc must normalize BOTH to the same 10-char date, and
// leave the field undefined when the key is absent so downstream staleness signals stay honest.
describe("parseDoc — reviewedAt (last_reviewed frontmatter)", () => {
  it("normalizes a quoted string last_reviewed to YYYY-MM-DD", () => {
    const md = `---
id: y
last_reviewed: "2026-07-01"
---
body`;
    const { nodes } = parseDoc({ path: "x/y.md", content: md }, REPOS);
    expect(nodes[0].reviewedAt).toBe("2026-07-01");
  });

  it("normalizes an ISO string with a time component to just the date", () => {
    const md = `---
id: y
last_reviewed: "2026-07-01T12:34:56Z"
---
body`;
    const { nodes } = parseDoc({ path: "x/y.md", content: md }, REPOS);
    expect(nodes[0].reviewedAt).toBe("2026-07-01");
  });

  it("normalizes a YAML Date object (unquoted timestamp) to YYYY-MM-DD", () => {
    const md = `---
id: y
last_reviewed: 2026-07-01
---
body`;
    const { data } = matter(md);
    // Guard the premise: the YAML engine really did hand us a Date, not a string.
    expect(data.last_reviewed instanceof Date).toBe(true);
    const { nodes } = parseDoc({ path: "x/y.md", content: md }, REPOS);
    expect(nodes[0].reviewedAt).toBe("2026-07-01");
  });

  it("leaves reviewedAt undefined when last_reviewed is absent", () => {
    const md = `---
id: y
title: No review date
---
body`;
    const { nodes } = parseDoc({ path: "x/y.md", content: md }, REPOS);
    expect(nodes[0].reviewedAt).toBeUndefined();
  });
});

import { describe, it, expect } from "vitest";
import { REPOS } from "./topology.fixture";
import { parseFeatures } from "./parseFeatures";

const yaml = `
- id: add.mapping
  label: Column mapping
  flow: add
  paths:
    - "**/addProperty/steps/step2/ColumnMappingStage.test.tsx"
    - "**/svc_ai/**column_mapping**"
- id: add.validate
  label: Data review & validation
  flow: add
  paths: ["**/rowValidation.test.ts"]
- { }
`;

describe("parseFeatures", () => {
  const { nodes, edges } = parseFeatures({ path: "svc_frontend/e2e/features/onboarding.features.yaml", content: yaml }, REPOS);

  it("creates one feature node per entry, skipping entries without an id", () => {
    expect(nodes.map((n) => n.id).sort()).toEqual(["frontend:add.mapping", "frontend:add.validate"]);
    expect(nodes.every((n) => n.type === "feature")).toBe(true);
  });

  it("namespaces the id by repo and keeps the authored dotted slug", () => {
    const m = nodes.find((n) => n.id === "frontend:add.mapping")!;
    expect(m.title).toBe("Column mapping");
    expect(m.flow).toBe("add");
    expect(m.paths).toEqual([
      "**/addProperty/steps/step2/ColumnMappingStage.test.tsx",
      "**/svc_ai/**column_mapping**",
    ]);
  });

  it("defaults title to the id and paths to [] when omitted", () => {
    const bare = parseFeatures({ path: "svc_frontend/e2e/features/x.features.yaml", content: "- id: add.dup" }, REPOS);
    expect(bare.nodes[0]).toMatchObject({ id: "frontend:add.dup", title: "add.dup", paths: [] });
  });

  it("emits no edges (tag edges are derived elsewhere)", () => {
    expect(edges).toEqual([]);
  });

  it("emits requirement nodes + a feature→requirement `specifies` edge, carrying provenBy", () => {
    const reqYaml = `
- id: pfl.scenario
  label: Scenario modeling
  flow: pfl
  paths: ["**/x.test.ts"]
  requirements:
    - id: REQ-PFL-SCEN-01
      text: Removing a member and running recomputes the KPIs.
      covers: [PFL-1]
    - text: The Run button is disabled until an edit is applied.
- id: pfl.page
  label: Pricing Scenario — overview
  flow: pfl
  page: true
  paths: []
  requirements:
    - id: REQ-PFL-PAGE-01
      text: The page models levers without mutating saved data.
`;
    const { nodes, edges } = parseFeatures({ path: "svc_frontend/e2e/features/pricing.features.yaml", content: reqYaml }, REPOS);
    const reqs = nodes.filter((n) => n.type === "requirement");
    expect(reqs.map((r) => r.id).sort()).toEqual(["REQ-FRONTEND-PFL-SCENARIO-2", "REQ-PFL-PAGE-01", "REQ-PFL-SCEN-01"]); // authored ids kept; auto id (namespaced) for the untitled one
    const scen = reqs.find((r) => r.id === "REQ-PFL-SCEN-01")!;
    expect(scen.title).toBe("Removing a member and running recomputes the KPIs.");
    expect(scen.provenBy).toEqual(["PFL-1"]);
    // the page feature is flagged
    expect(nodes.find((n) => n.id === "frontend:pfl.page")!.page).toBe(true);
    // feature → requirement specifies edges
    expect(edges).toContainEqual({ from: "frontend:pfl.scenario", to: "REQ-PFL-SCEN-01", type: "specifies", source: "svc_frontend/e2e/features/pricing.features.yaml" });
    expect(edges.filter((e) => e.type === "specifies").length).toBe(3);
  });

  it("parses `star: true` as a feature-node favourite flag (defaults undefined)", () => {
    const starYaml = `
- id: bil.versions
  label: Versions
  flow: bil
  star: true
  paths: []
- id: bil.leasing
  label: Leasing
  flow: bil
  paths: []
- id: bil.macro
  label: Macro
  flow: bil
  star: false
  paths: []
`;
    const { nodes } = parseFeatures({ path: "svc_frontend/e2e/features/billing.features.yaml", content: starYaml }, REPOS);
    const byId = Object.fromEntries(nodes.map((n) => [n.id, n]));
    expect(byId["frontend:bil.versions"].star).toBe(true);
    expect(byId["frontend:bil.leasing"].star).toBeUndefined();  // omitted → undefined, not false, so consumers can use truthy check
    expect(byId["frontend:bil.macro"].star).toBeUndefined();    // explicit false also normalises to undefined — the field is a flag, not a tri-state
  });

  // PIN (provenance contract, not TDD — locks existing behaviour): the serve-mode
  // `/registry/<basename>` + GitHub-blob provenance links resolve a requirement's
  // origin from `node.path`, so requirement nodes MUST carry `path` equal to the
  // registry yaml they were authored in (parseFeatures.ts stamps `path: input.path`
  // on both feature and requirement nodes). If this ever regresses, registry
  // provenance links in the viewer silently vanish — fail loudly here instead.
  it("PIN: requirement nodes carry `path` = the registry yaml path they came from", () => {
    const regPath = "svc_frontend/e2e/features/underwriting.features.yaml";
    const { nodes } = parseFeatures({
      path: regPath,
      content: `
- id: uw.deal-return
  label: Deal return
  flow: uw
  paths: []
  requirements:
    - id: REQ-FIN-DEALRETURN-03
      text: A messy upload still renders a deal return after blocking errors are resolved.
    - text: An untitled requirement also inherits the registry path.
`,
    }, REPOS);
    const reqs = nodes.filter((n) => n.type === "requirement");
    expect(reqs.length).toBe(2);
    for (const r of reqs) expect(r.path).toBe(regPath);
    // the feature node carries the same provenance path
    expect(nodes.find((n) => n.type === "feature")!.path).toBe(regPath);
  });

  it("tolerates a mis-authored non-list root (mapping/scalar/empty) without throwing", () => {
    // A registry authored as a top-level mapping or scalar must not abort the build.
    expect(() => parseFeatures({ path: "x.features.yaml", content: "id: add.oops\nlabel: nope" }, REPOS)).not.toThrow();
    expect(parseFeatures({ path: "x.features.yaml", content: "id: add.oops" }, REPOS).nodes).toEqual([]);
    expect(parseFeatures({ path: "x.features.yaml", content: "" }, REPOS).nodes).toEqual([]);
    expect(parseFeatures({ path: "x.features.yaml", content: "just a string" }, REPOS).nodes).toEqual([]);
  });
});

import { describe, it, expect } from "vitest";
import { parsePlaywrightJson, parseCaseResult } from "./parsePlaywrightReport";
const report = JSON.stringify({
  suites: [{ title: "billing.spec.ts", suites: [{ title: "bil", specs: [
    { title: "bil one", ok: true, tests: [{ results: [{ status: "failed" }, { status: "passed" }] }] },
  ] }], specs: [
    { title: "bil two", ok: false, tests: [{ results: [{ status: "failed" }, { status: "failed" }] }] },
  ] }],
});
describe("parsePlaywrightJson", () => {
  const titles = new Map([["bil one", "bil-1"], ["bil two", "bil-2"]]);
  const r = parsePlaywrightJson(report, titles);
  it("maps titles to case ids with pass/fail + attempts (nested suites)", () => {
    expect(r["bil-1"]).toEqual({ status: "pass", attempts: 2 });
    expect(r["bil-2"]).toEqual({ status: "fail", attempts: 2 });
  });
  it("ignores specs whose title is not a known case", () => {
    expect(Object.keys(r).sort()).toEqual(["bil-1", "bil-2"]);
  });

  // Regression: a batch whose auth setup failed reports its tests as "did not
  // run" — `ok: true` with an EMPTY results array. Recording those as `pass`
  // fabricates a green result for a test that never executed (observed live:
  // "newly passing: frontend:UW-6" from a run where UW-6 never ran, recorded
  // as `pass, attempts: 0` in kg-test-results.json).
  it("does NOT record a spec whose tests never ran (ok:true, empty results)", () => {
    const didNotRun = JSON.stringify({
      suites: [{ title: "s.spec.ts", specs: [
        { title: "never ran", ok: true, tests: [{ results: [] }] },
      ] }],
    });
    const out = parsePlaywrightJson(didNotRun, new Map([["never ran", "uw-6"]]));
    expect(out).toEqual({});
  });

  it("does NOT record a spec whose only results are skipped (fixme/serial-skip)", () => {
    const skippedOnly = JSON.stringify({
      suites: [{ title: "s.spec.ts", specs: [
        { title: "skipped case", ok: true, tests: [{ results: [{ status: "skipped" }] }] },
      ] }],
    });
    const out = parsePlaywrightJson(skippedOnly, new Map([["skipped case", "uw-6"]]));
    expect(out).toEqual({});
  });

  // Serial-mode retry: a test skipped in the first chain (an earlier serial
  // test failed) and executed once on the chain retry has results
  // [skipped, passed] — one REAL attempt, not two (attempts=2 previously
  // mislabelled such passes as "flaky").
  it("counts only executed (non-skipped) results as attempts", () => {
    const serialRetry = JSON.stringify({
      suites: [{ title: "s.spec.ts", specs: [
        { title: "ran after skip", ok: true, tests: [{ results: [{ status: "skipped" }, { status: "passed" }] }] },
      ] }],
    });
    const out = parsePlaywrightJson(serialRetry, new Map([["ran after skip", "uw-5"]]));
    expect(out).toEqual({ "uw-5": { status: "pass", attempts: 1 } });
  });
});

// R2-B last-run visibility: failed cases carry a cleaned `error` string extracted from the
// Playwright JSON reporter's per-result error objects (ANSI-colored, multi-line, may embed
// filesystem-absolute paths). Passing cases must NOT carry one.
describe("parsePlaywrightJson — error extraction (failed cases)", () => {
  const failedReport = (message: string) => JSON.stringify({
    suites: [{ title: "s.spec.ts", specs: [
      { title: "t", ok: false, tests: [{ results: [{ status: "failed", errors: [{ message }] }, { status: "failed", errors: [{ message: "second-attempt error (must not win)" }] }] }] },
    ] }],
  });
  const titles = new Map([["t", "uw-8"]]);

  it("extracts the FIRST error message, ANSI-stripped, first non-empty lines only", () => {
    const ansi = "\u001b[31mError: expect(locator).toBeVisible() failed\u001b[39m\n\n\u001b[2mLocator: getByTestId('deal-return')\u001b[22m";
    const out = parsePlaywrightJson(failedReport(ansi), titles);
    expect(out["uw-8"].status).toBe("fail");
    expect(out["uw-8"].error).toBe("Error: expect(locator).toBeVisible() failed\nLocator: getByTestId('deal-return')");
    expect(out["uw-8"].error).not.toContain("\u001b");
    expect(out["uw-8"].error).not.toContain("second-attempt");
  });

  // The repo folder names are config-derived now (repoDirNames(config, repoRoot) at the call sites),
  // so the test states them instead of relying on a literal baked into the module.
  const REPO_DIRS = ["ws_root", "svc_frontend", "svc_backend"];

  it("strips filesystem-absolute path prefixes down to repo-relative", () => {
    const msg = "Error: boom\n    at C:\\Users\\ching\\workspace\\ws_root\\svc_frontend\\e2e\\uw.spec.ts:42:5";
    const out = parsePlaywrightJson(failedReport(msg), titles, REPO_DIRS);
    expect(out["uw-8"].error).not.toMatch(/[A-Za-z]:\\/);
    expect(out["uw-8"].error).toContain("e2e\\uw.spec.ts:42:5");
  });

  // A path under a directory the workspace does not contain is left alone — the stripper must not
  // guess at an arbitrary absolute prefix, only reduce ones it can name.
  it("leaves an unrelated absolute path untouched", () => {
    const msg = "Error: boom\n    at /opt/homebrew/lib/node_modules/x.js:1:1";
    const out = parsePlaywrightJson(failedReport(msg), titles, REPO_DIRS);
    expect(out["uw-8"].error).toContain("/opt/homebrew/lib/node_modules/x.js:1:1");
  });

  // Degenerate case: no names to match. Must strip NOTHING — an empty alternation would match at
  // every position and eat the message.
  it("strips nothing when given no repo dir names", () => {
    const msg = "Error: boom\n    at /a/b/c.spec.ts:1:1";
    const out = parsePlaywrightJson(failedReport(msg), titles, []);
    expect(out["uw-8"].error).toContain("/a/b/c.spec.ts:1:1");
  });

  it("truncates to ~300 chars with an ellipsis", () => {
    const out = parsePlaywrightJson(failedReport("E".repeat(500)), titles);
    expect(out["uw-8"].error!.length).toBeLessThanOrEqual(300);
    expect(out["uw-8"].error!.endsWith("…")).toBe(true);
  });

  it("falls back to result.error.message when errors[] is absent", () => {
    const rep = JSON.stringify({
      suites: [{ title: "s.spec.ts", specs: [
        { title: "t", ok: false, tests: [{ results: [{ status: "failed", error: { message: "Error: timed out" } }] }] },
      ] }],
    });
    expect(parsePlaywrightJson(rep, titles)["uw-8"].error).toBe("Error: timed out");
  });

  it("failed case with no error object in the report gets no error field", () => {
    const rep = JSON.stringify({
      suites: [{ title: "s.spec.ts", specs: [
        { title: "t", ok: false, tests: [{ results: [{ status: "failed" }] }] },
      ] }],
    });
    const e = parsePlaywrightJson(rep, titles)["uw-8"];
    expect(e.status).toBe("fail");
    expect("error" in e).toBe(false);
  });

  it("passing cases carry NO error field even when a retried attempt failed first", () => {
    const rep = JSON.stringify({
      suites: [{ title: "s.spec.ts", specs: [
        { title: "t", ok: true, tests: [{ results: [{ status: "failed", errors: [{ message: "flaky first attempt" }] }, { status: "passed" }] }] },
      ] }],
    });
    const e = parsePlaywrightJson(rep, titles)["uw-8"];
    expect(e.status).toBe("pass");
    expect("error" in e).toBe(false);
  });
});

describe("parseCaseResult — single live run (2a)", () => {
  const rep = (spec: object) => JSON.stringify({ suites: [{ title: "s.spec.ts", specs: [spec] }] });

  it("pass: status pass, no error, no screenshots", () => {
    const r = parseCaseResult(rep({ title: "t", ok: true, tests: [{ results: [{ status: "passed" }] }] }), "t", ["ws_root", "svc_frontend", "svc_backend"]);
