      status: "failed",
      errors: [{ message: "[31mError: boom[39m" }],
      attachments: [
        { name: "screenshot", contentType: "image/png", path: "C:\\Users\\x\\svc_frontend\\test-results\\t\\test-failed-1.png" },
        { name: "trace", contentType: "application/zip", path: "C:\\x\\trace.zip" },
