    expect(n.title).toBe("rowValidation.test.ts");
    expect(n.text).toBe("deriveCompletenessErrors — cycle tenant/trade detection");
    expect(n.testCount).toBe(2);
    expect(n.status).toBe("pass"); // authored/derived default until run results override
    expect(n.source).toBe(feContent); // full file source carried for the viewer's view-source
  });

  it("extracts a `summary` from the leading // comment block (FE) and the module docstring (BE)", () => {
    // CRLF line endings on purpose — Windows checkouts use them, and a naive `$`-anchored
    // line scan silently misses `//` comment runs on CRLF files.
    const feWithComment = [
      'import { describe, it, expect } from "vitest";',
      'import { evaluateAnalysisDateChange } from "./analysisDateGuard";',
      '',
      '// eslint-disable-next-line',
      '// Both Step 1 and Step 2 pipe analysis-date changes through these helpers.',
      '// Tests pin the gate so the two surfaces never silently drift apart again.',
      'describe("evaluateAnalysisDateChange", () => {',
      '  it("returns noop when the new date equals the current date", () => {});',
      '});',
    ].join("\r\n");
    const fe = parseUnitTest({ path: "svc_frontend/src/a.test.ts", content: feWithComment }, REPOS).nodes[0];
    expect(fe.text).toBe("evaluateAnalysisDateChange"); // the "what"
    expect(fe.summary).toBe("Both Step 1 and Step 2 pipe analysis-date changes through these helpers. Tests pin the gate so the two surfaces never silently drift apart again."); // the "why", eslint directive skipped

    const be = parseUnitTest({ path: "svc_backend/tests/test_x.py", content: beContent }, REPOS).nodes[0];
    expect(be.summary).toBe("Contract tests for the update_property_rent_roll stored procedure. Pins that existing units are updated in place, never deleted.");

    // A file with no leading comment gets no summary (viewer falls back to the title alone).
    expect(parseUnitTest({ path: "svc_frontend/src/b.test.ts", content: feContent }, REPOS).nodes[0].summary).toBeUndefined();
  });

  it("counts chained test forms (it.each/it.only/test.skip) and ignores method calls like regex.test(", () => {
    const src = `import { describe, it, test, expect } from "vitest";
describe("counting", () => {
  it("a", () => {});
  it.each([1,2])("b %s", () => {});
  it.only("c", () => {});
  test.skip("d", () => {});
  test("e", () => { expect(/x/.test("x")).toBe(true); });
});`;
    const { nodes } = parseUnitTest({ path: "svc_frontend/src/foo.test.ts", content: src }, REPOS);
    // it, it.each, it.only, test.skip, test → 5; the `.test(` method call is NOT counted.
    expect(nodes[0].testCount).toBe(5);
  });

  it("parses a pytest file into a unit-be node (docstring description, def test_ count)", () => {
    const { nodes } = parseUnitTest({
      path: "svc_backend/tests/test_update_property_rent_roll_sql_contract.py",
      content: beContent,
    }, REPOS);
    const n = nodes[0];
    expect(n.kind).toBe("unit-be");
    expect(n.id).toBe("backend:tests/test_update_property_rent_roll_sql_contract.py");
    expect(n.title).toBe("test_update_property_rent_roll_sql_contract.py");
    expect(n.text).toBe("Contract tests for the update_property_rent_roll stored procedure.");
    expect(n.testCount).toBe(3);
  });
});

/**
 * `covers:` in a unit test (CEO 2026-07-24). Until now the ONLY way a requirement got a covering
 * test was a `*.cases.yaml` or a feature registry — both e2e artifacts — so a project with no UI
 * flows could never prove a requirement at all. This tool is exactly that project: 39 requirements,
 * 485 tests, and every requirement reading `uncovered`.
 *
 * Comment-anchored on purpose: a bare `covers:` appearing in test data or a string literal must not
 * be mistaken for a declaration.
 */
describe("declared covers", () => {
  const req = (src: string) => parseUnitTest({ path: "src/x.test.ts", content: src }, REPOS).edges;

  it("links a test to the requirement it declares it proves", () => {
    const e = req(`// covers: REQ-KG-01\nit('x', () => {})`);
    expect(e).toEqual([{ from: "main:src/x.test.ts", to: "REQ-KG-01", type: "covers", source: "src/x.test.ts" }]);
  });

  it("accepts several ids on one line", () => {
    expect(req(`// covers: REQ-A, REQ-B\n`).map((x) => x.to)).toEqual(["REQ-A", "REQ-B"]);
  });

  it("reads a JSDoc block and a python comment", () => {
    expect(req(`/**\n * covers: REQ-A\n */`).map((x) => x.to)).toEqual(["REQ-A"]);
    expect(
      parseUnitTest({ path: "tests/test_x.py", content: `# covers: REQ-B\n` }, REPOS).edges.map((x) => x.to),
    ).toEqual(["REQ-B"]);
  });

  it("does not mistake a covers: inside test data for a declaration", () => {
    expect(req(`it('x', () => { expect(y).toBe("covers: REQ-FAKE") })`)).toEqual([]);
  });

  it("emits nothing when the test declares nothing", () => {
    expect(req(`it('x', () => {})`)).toEqual([]);
  });
});

// covers: REQ-KG-SERVE-02
import { describe, it, expect } from "vitest";
import { sep } from "node:path";
import { isWithinRoot } from "./pathGuard";

// Inputs mirror how callers actually use this guard: both `root` and `abs`
// are already `normalize()`d filesystem paths, so they use the platform's
// native separator (`sep`) — never a hardcoded "/".
const p = (...parts: string[]) => parts.join(sep);

describe("isWithinRoot", () => {
  it("accepts a path inside the root", () => {
    expect(isWithinRoot(p("a", "shots"), p("a", "shots", "case", "1.png"))).toBe(true);
  });

  it("accepts the root itself", () => {
    expect(isWithinRoot(p("a", "shots"), p("a", "shots"))).toBe(true);
  });

  it("rejects a sibling directory whose name merely starts with the root's name (boundary case)", () => {
    // Root ".../shots" must NOT match ".../shots-evil" — a naive
    // `abs.startsWith(root)` check would wrongly accept this because the
    // string "shots-evil/x" starts with the string "shots".
    expect(isWithinRoot(p("a", "shots"), p("a", "shots-evil", "x.png"))).toBe(false);
  });

  it("rejects a real traversal (../ escape resolved to outside root)", () => {
    expect(isWithinRoot(p("a", "shots"), p("a", "other"))).toBe(false);
  });

  it("tolerates a root already carrying a trailing separator", () => {
    expect(isWithinRoot(p("a", "shots") + sep, p("a", "shots", "case", "1.png"))).toBe(true);
    expect(isWithinRoot(p("a", "shots") + sep, p("a", "shots-evil", "x.png"))).toBe(false);
  });
});

// recordRun's pure pieces, fed a FABRICATED Playwright JSON report (with screenshot
// attachments) + a graph fixture. Proves:
//   (i)   kg-test-results.json entries update with status + error (via parsePlaywrightJson + merge);
//   (ii)  each test's screenshot attachment resolves to the .step-shots/<dirId>/<dirId>-result.png copy;
//   (iii) title→case resolution keys results LOWERCASE (applyResults lookup) but the shot dir keeps
//         the ORIGINAL bare id, and UNMAPPED tests (auth setup) are skipped entirely.
import { describe, it, expect } from "vitest";
import { caseTitleMap, resolveResultShots, type ResultShot } from "./recordRun";
import { parsePlaywrightJson } from "./parsePlaywrightReport";
import type { Graph } from "./types";

const graph = {
  generatedAt: "T",
  nodes: [
    { id: "frontend:ADD-4", type: "test", title: "ADD-4", kind: "e2e", spec: "onboarding-scenarios.spec.ts", playwrightTitle: "a wizard draft persists and can be resumed" },
    { id: "frontend:UW-8", type: "test", title: "UW-8", kind: "e2e", spec: "underwrite.spec.ts", playwrightTitle: "UW-8 reverse yield" },
    { id: "frontend:BIL-1", type: "test", title: "BIL-1", kind: "unit-fe" }, // not e2e → not in map
  ],
  edges: [], issues: [],
} as unknown as Graph;

// Fabricated Playwright JSON report: one passing e2e with a screenshot, one failing e2e with
// two attempts (last attempt's shot must win), plus an auth-setup spec that maps to NO case.
const report = JSON.stringify({
  suites: [
    { title: "onboarding-scenarios.spec.ts", specs: [
      { title: "a wizard draft persists and can be resumed", ok: true, tests: [{ results: [
        { status: "passed", attachments: [{ name: "screenshot", contentType: "image/png", path: "/tmp/pw/add4/test-finished-1.png" }] },
      ] }] },
    ] },
    { title: "underwrite.spec.ts", specs: [
      { title: "UW-8 reverse yield", ok: false, tests: [{ results: [
        { status: "failed", errors: [{ message: "Error: expect(locator).toBeVisible() failed" }], attachments: [{ name: "screenshot", contentType: "image/png", path: "/tmp/pw/uw8/attempt-0.png" }] },
        { status: "failed", errors: [{ message: "retry error" }], attachments: [{ name: "screenshot", contentType: "image/png", path: "/tmp/pw/uw8/attempt-1.png" }] },
      ] }] },
    ] },
    { title: "auth.setup.ts", specs: [
      { title: "authenticate via Supabase email + password", ok: true, tests: [{ results: [
        { status: "passed", attachments: [{ name: "screenshot", contentType: "image/png", path: "/tmp/pw/setup/x.png" }] },
      ] }] },
    ] },
  ],
});

describe("caseTitleMap", () => {
  const map = caseTitleMap(graph);
  it("maps each e2e playwrightTitle to its lowercase caseId + original-cased dirId", () => {
    expect(map.get("a wizard draft persists and can be resumed")).toEqual({ caseId: "add-4", dirId: "ADD-4" });
    expect(map.get("UW-8 reverse yield")).toEqual({ caseId: "uw-8", dirId: "UW-8" });
  });
  it("excludes non-e2e tests and titles with no playwrightTitle", () => {
    expect(map.size).toBe(2);
  });
});

describe("resolveResultShots", () => {
  const map = caseTitleMap(graph);
  const shots = resolveResultShots(report, map);
  const byDir = (id: string) => shots.find((s: ResultShot) => s.dirId === id);

  it("resolves a screenshot for each mapped case", () => {
    expect(shots.length).toBe(2);
  });
  it("copies to .step-shots/<dirId>/<dirId>-result.png with the ORIGINAL bare id", () => {
    expect(byDir("ADD-4")).toEqual({ dirId: "ADD-4", srcPath: "/tmp/pw/add4/test-finished-1.png", destName: "ADD-4-result.png" });
  });
  it("prefers the LAST (failure/final) attempt's screenshot for a retried failing case", () => {
    expect(byDir("UW-8")!.srcPath).toBe("/tmp/pw/uw8/attempt-1.png");
  });
  it("skips the unmapped auth-setup spec entirely (no shot for it)", () => {
    expect(shots.some((s) => s.srcPath.includes("/setup/"))).toBe(false);
  });
});

// Integration-ish pin: the SAME report drives parsePlaywrightJson (results) keyed by lowercase
// caseId, proving recordRun's two halves agree on casing.
describe("recordRun results half stays consistent with the shot half", () => {
  const map = caseTitleMap(graph);
  const titles = new Map([...map.entries()].map(([t, v]) => [t, v.caseId]));
  const results = parsePlaywrightJson(report, titles);
  it("records status + error for failing case, keyed lowercase", () => {
    expect(results["uw-8"].status).toBe("fail");
    expect(results["uw-8"].error).toContain("expect(locator).toBeVisible() failed");
    expect(results["add-4"].status).toBe("pass");
  });
  it("does not record the unmapped auth-setup spec", () => {
    expect(Object.keys(results).sort()).toEqual(["add-4", "uw-8"]);
  });
});

import { describe, it, expect } from "vitest";
import fg from "fast-glob";
import { readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

/**
 * REQ-0 — Given any repo root supplied as configuration, the tool builds a byte-identical graph to the
 * one the origin project's in-tree copy produced, KNOWING NOTHING ABOUT THAT PROJECT.
 *
 * This is the project's requirement zero, approved by the CEO on 2026-07-17 before any code was ported.
 *
 * Why grep, and not "build two graphs and compare": the byte-identical half needs the origin project's
 * private repo, so it can never run in this repo's CI or survive distribution. "Names no consuming
 * project" is the half that CAN be asserted here, forever, by anyone who installs the tool — and it is
 * the half that actually decays.
 *
 * SCOPE IS THE WHOLE REPO, not `src/`. It used to scan `src/*.ts` only, and everything outside that one
 * directory quietly kept its coupling: the SHIPPED VIEWER TEMPLATE hardcoded the origin project's repo
 * directories, GitHub org and working branch, so every installed copy rendered that project's name in
 * its title bar and built source links to directories the user does not have. A requirement text still
 * described a fixed three-repo table the code had already stopped using. None of it was caught, because
 * the guard was pointed at the one place that had already been cleaned.
 *
 * THE NAME-GREP IS GONE, and deliberately not replaced with a cleverer spelling of itself. To grep for
 * a word you must store the word — split across an array, hashed, however coy — and the CEO's
 * instruction was that the repo contain it in no form at all. Storing it split would also have put it
 * straight back into `knowledge-graph.json` and `viewer.html`, since `src/**\/*.test.ts` is indexed.
 *
 * Losing it costs less than it appears, because it was always the WEAKER half. §12.14: a name-grep
 * "goes green when the tool stops NAMING the origin project — not when the tool stops ASSUMING it."
 * That was not theoretical. Every coupling actually found on 2026-07-24 — the viewer's hardcoded repo
 * directories, its forge org and working branch, and `FLOW_LABELS`' table of another company's product
 * surfaces — contained no project name, so the grep was green throughout.
 *
 * What replaces it are guards that cannot be satisfied by a rename:
 *   - REQ-1's fixture byte-identity tests (`fixtureRepo.test.ts`), which the founding design already
 *     names REQ-0's permanent successor: a tool that assumes a layout builds the wrong fixture graph
 *     whether or not it ever names a project;
 *   - the assertions below, which forbid the SHAPES of coupling rather than one project's spelling.
 */

const SRC = dirname(fileURLToPath(import.meta.url));
const REPO = join(SRC, "..");

/** Build output, vcs internals, and the synthetic fixture projects (which are their own repos, and are
 *  already asserted clean by their committed expected graphs). */
const IGNORE = [
  "**/node_modules/**",
  "**/.git/**",
  "**/dist/**",
  "**/.next/**",
  "package-lock.json",
];

/** Text files only — a binary would produce noise, not a finding. */
const TEXT = /\.(ts|tsx|mts|js|mjs|json|md|html|yaml|yml|txt|sh)$/i;

async function repoFiles(): Promise<string[]> {
  const all = await fg("**/*", { cwd: REPO, ignore: IGNORE, dot: true, unique: true, onlyFiles: true });
  return all.filter((p) => TEXT.test(p)).sort();
}

/** The shipped surface: what an installed copy actually carries. Tests are excluded — a fixture is
 *  allowed to describe a made-up project, that is what a fixture is for. */
const SHIPPED = ["viewer.template.html", "src/summarize.ts", "src/viewer.ts", "src/digest.ts", "src/serve.ts"];

describe("REQ-0 — the tool assumes nothing about the project it measures", () => {
  it("scans the shipped viewer template, the asset that escaped the old src/-only guard", async () => {
    const files = await repoFiles();
    // A guard that silently matched nothing would pass forever. Pin that it actually walked the tree.
    expect(files.length, "the lint found no files to scan — the walk is broken").toBeGreaterThan(50);
    expect(files).toContain("viewer.template.html");
  });

  // A hardcoded forge host, owner and branch sent every installed copy into a stranger's repository.
  // Unlike a project name, this survives any rename, which is why it is asserted by shape.
  it("builds no hardcoded forge URL in any shipped asset", async () => {
    const offenders: string[] = [];
    for (const rel of SHIPPED) {
      const text = await readFile(join(REPO, rel), "utf8").catch(() => "");
      const urls = text.match(/https?:\/\/(www\.)?(github|gitlab|bitbucket)\.com\/[^'"\s)]+/g) ?? [];
      // `api.github.com` is legitimate: the evidence-image fetch, whose token the user supplies.
      const bad = urls.filter((u) => !u.includes("api.github.com"));
      if (bad.length) offenders.push(`${rel}: ${bad.join(", ")}`);
    }
    expect(offenders, `shipped assets hardcode a forge: ${offenders.join(" | ")}`).toEqual([]);
  });

  // `FLOW_LABELS` was a lookup table of one project's product surfaces, rendered as everyone's flow
  // taxonomy. A flow's name belongs to whichever project declared it in its own *.features.yaml.
  it("ships no product taxonomy — flow labels come from the project, not the tool", async () => {
    const { FLOW_LABELS } = await import("./summarize");
    // `other` is the tool's OWN bucket for features declaring no flow; everything else would be borrowed.
    expect(Object.keys(FLOW_LABELS)).toEqual(["other"]);
  });

  // The name was only half of it. The shipped viewer also hardcoded a forge host, an owner and a
  // working branch, so every installed copy linked its user into a stranger's repository. The tool is
  // told none of those three, so it must construct no such URL at all — and unlike the name, a forge
  // literal would survive a rename of the origin project, which is why it gets its own assertion.
  it("the shipped viewer builds no hardcoded forge URL", async () => {
    const template = await readFile(join(REPO, "viewer.template.html"), "utf8");
    const forgeUrls = template.match(/https?:\/\/(www\.)?(github|gitlab|bitbucket)\.com\/[^'"\s)]+/g) ?? [];
    // `api.github.com` is legitimate: it is the evidence-image fetch, and the user supplies its token.
    expect(forgeUrls.filter((u) => !u.includes("api.github.com"))).toEqual([]);
  });
});

import { describe, it, expect } from "vitest";
import { join } from "node:path";
import { resolveBackendVenvPython } from "./resolveBackendVenvPython";

const repoRoot = "/repo";
const backendDir = "/repo/svc_backend";

describe("resolveBackendVenvPython", () => {
  it("picks the backend-package venv when only that layout exists (this repo's actual layout)", () => {
    const rootVenvPython = join(repoRoot, ".venv", "bin", "python");
    const backendVenvPython = join(backendDir, ".venv", "bin", "python");
    const exists = (p: string) => p === backendVenvPython;

    const resolved = resolveBackendVenvPython(repoRoot, backendDir, "darwin", exists, join);

    expect(resolved).toBe(backendVenvPython);
    expect(resolved).not.toBe(rootVenvPython);
  });

  it("picks the root venv when only that layout exists", () => {
    const rootVenvPython = join(repoRoot, ".venv", "bin", "python");
    const exists = (p: string) => p === rootVenvPython;

    expect(resolveBackendVenvPython(repoRoot, backendDir, "darwin", exists, join)).toBe(rootVenvPython);
  });

  it("prefers the root venv when both layouts exist", () => {
    const rootVenvPython = join(repoRoot, ".venv", "bin", "python");
    const exists = () => true;

    expect(resolveBackendVenvPython(repoRoot, backendDir, "darwin", exists, join)).toBe(rootVenvPython);
  });

  it("falls back to the root-level path when neither exists yet", () => {
    const rootVenvPython = join(repoRoot, ".venv", "bin", "python");
    const exists = () => false;

    expect(resolveBackendVenvPython(repoRoot, backendDir, "darwin", exists, join)).toBe(rootVenvPython);
  });

  it("uses the Windows Scripts/python.exe layout on win32", () => {
    const winRootVenvPython = join(repoRoot, ".venv", "Scripts", "python.exe");
    const exists = (p: string) => p === winRootVenvPython;

    expect(resolveBackendVenvPython(repoRoot, backendDir, "win32", exists, join)).toBe(winRootVenvPython);
  });
});

import { describe, it, expect } from "vitest";
