// covers: REQ-KG-SERVE-04
import { describe, it, expect } from "vitest";
import { toggleStarInYaml } from "./toggleStar";

const doc = `# a comment
- id: fin.deal-return
  label: Deal return
  flow: fin
  paths:
    - "**/deal/**"
- id: fin.engine
  label: Financial engine
  flow: fin
`;

describe("toggleStarInYaml", () => {
  it("adds `star: true` right under the matching id line, indented like siblings", () => {
    const out = toggleStarInYaml(doc, "fin.deal-return", true);
    expect(out).toContain("- id: fin.deal-return\n  star: true\n  label: Deal return");
    // untouched sibling
    expect(out).toContain("- id: fin.engine\n  label: Financial engine");
  });

  it("is idempotent when adding to an entry that is already starred", () => {
    const once = toggleStarInYaml(doc, "fin.deal-return", true);
    const twice = toggleStarInYaml(once, "fin.deal-return", true);
    expect(twice).toBe(once);
  });

  it("removes the `star: true` line when unstarring", () => {
    const starred = toggleStarInYaml(doc, "fin.deal-return", true);
    const cleared = toggleStarInYaml(starred, "fin.deal-return", false);
    expect(cleared).toBe(doc);
  });

  it("unstarring an entry that is not starred is a no-op", () => {
    expect(toggleStarInYaml(doc, "fin.engine", false)).toBe(doc);
  });

  it("only touches the targeted entry, not one whose id is a prefix/substring", () => {
    const two = `- id: fin.deal
  label: Deal
- id: fin.deal-return
  label: Deal return
`;
    const out = toggleStarInYaml(two, "fin.deal", true);
    expect(out).toBe(`- id: fin.deal
  star: true
  label: Deal
- id: fin.deal-return
  label: Deal return
`);
  });

  it("matches a quoted id value", () => {
    const q = `- id: "fin.deal-return"\n  label: Deal return\n`;
    expect(toggleStarInYaml(q, "fin.deal-return", true)).toContain('- id: "fin.deal-return"\n  star: true\n');
  });

  it("throws when the feature id is not found", () => {
    expect(() => toggleStarInYaml(doc, "nope.missing", true)).toThrow(/not found/i);
  });

  it("flips an explicit `star: false` to true in place (no duplicate line)", () => {
    const withFalse = `- id: fin.engine\n  star: false\n  label: Financial engine\n`;
    const out = toggleStarInYaml(withFalse, "fin.engine", true);
    expect(out).toBe(`- id: fin.engine\n  star: true\n  label: Financial engine\n`);
  });

  // Regression: the star scan must be depth-anchored — a key literally named
  // `star` nested inside the entry (deeper indent) must never be matched,
  // overwritten, or deleted.
  const nested = `- id: fin.x
  label: X
  meta:
    star: nested-value
- id: fin.y
  label: Y
`;
  it("ignores a nested `star:` key when adding a top-level star", () => {
    const out = toggleStarInYaml(nested, "fin.x", true);
    expect(out).toBe(`- id: fin.x
  star: true
  label: X
  meta:
    star: nested-value
- id: fin.y
  label: Y
`);
  });

  it("does not delete a nested `star:` key when unstarring the entry", () => {
    // fin.x has no top-level star, only a nested one → unstarring is a no-op
    // and must leave the nested key intact.
    expect(toggleStarInYaml(nested, "fin.x", false)).toBe(nested);
  });
});

// covers: REQ-KG-RUN-04
import { describe, it, expect } from "vitest";
import { treeKillCommand } from "./treeKill";

// Pure command-construction logic for killing a whole process tree (a spawned
// `npx playwright test` child that itself forks Node workers + a headed
// Chrome). On Windows, `proc.kill()` only kills the immediate `npx.cmd`
// wrapper and leaks the rest of the tree (BUG-3 in the audit) — `taskkill
// /T /F` is required. Extracted as pure command construction so the exact
// argv is unit-testable without actually spawning/killing anything.
describe("treeKillCommand", () => {
  it("builds a taskkill invocation on win32", () => {
    expect(treeKillCommand("win32", 4242)).toEqual({
      cmd: "taskkill",
      args: ["/pid", "4242", "/T", "/F"],
    });
  });

  it("builds a POSIX SIGTERM signal invocation elsewhere", () => {
    expect(treeKillCommand("linux", 4242)).toEqual({ signal: "SIGTERM", pid: 4242 });
    expect(treeKillCommand("darwin", 4242)).toEqual({ signal: "SIGTERM", pid: 4242 });
  });

  it("coerces the pid to a string in the taskkill args (taskkill requires a string arg)", () => {
    const r = treeKillCommand("win32", 99);
    expect(r).toHaveProperty("args");
    if ("args" in r) expect(r.args).toEqual(["/pid", "99", "/T", "/F"]);
  });
});

import { describe, it, expect } from "vitest";
import { isTypeVisible } from "./typeVisibility";

describe("isTypeVisible", () => {
  it("defaults everything visible when vis is absent/empty/null", () => {
    expect(isTypeVisible({ type: "test", kind: "unit-fe" })).toBe(true);
    expect(isTypeVisible({ type: "cache-entry" }, {})).toBe(true);
    expect(isTypeVisible({ type: "test", kind: "unit-be" }, null)).toBe(true);
  });
  it("hides unit-fe tests only when 'unit-fe' is explicitly false", () => {
    expect(isTypeVisible({ type: "test", kind: "unit-fe" }, { "unit-fe": false })).toBe(false);
    expect(isTypeVisible({ type: "test", kind: "unit-fe" }, { "unit-fe": true })).toBe(true);
  });
  it("hides unit-be tests only when 'unit-be' is explicitly false", () => {
    expect(isTypeVisible({ type: "test", kind: "unit-be" }, { "unit-be": false })).toBe(false);
  });
  it("hides cache-entry nodes only when 'cache-entry' is explicitly false", () => {
    expect(isTypeVisible({ type: "cache-entry" }, { "cache-entry": false })).toBe(false);
    expect(isTypeVisible({ type: "cache-entry" }, { "cache-entry": true })).toBe(true);
  });
  it("a toggle only affects its own kind — hiding unit-fe leaves unit-be/e2e/cache visible", () => {
    const v = { "unit-fe": false };
    expect(isTypeVisible({ type: "test", kind: "unit-be" }, v)).toBe(true);
    expect(isTypeVisible({ type: "test", kind: "e2e" }, v)).toBe(true);
    expect(isTypeVisible({ type: "cache-entry" }, v)).toBe(true);
  });
  it("never hides non-hideable node types even when all flags are false", () => {
    const off = { "unit-fe": false, "unit-be": false, "cache-entry": false } as const;
    ["doc", "requirement", "instruction", "agent", "hook", "feature"].forEach((t) => {
      expect(isTypeVisible({ type: t }, off)).toBe(true);
    });
    expect(isTypeVisible({ type: "test", kind: "e2e" }, off)).toBe(true); // e2e is never hideable
  });
  it("a test node with no kind is always visible (not a hideable unit kind)", () => {
    expect(isTypeVisible({ type: "test" }, { "unit-fe": false, "unit-be": false })).toBe(true);
  });
});

// NO `covers:` YET — deliberately. The behaviour below implements founding design §10.3, but §10.3 is
// a decision, not a requirement, and the REQ that would state it (REQ-KG-CTX-02, drafted for the CEO)
// is not approved. Pointing `covers:` at an unapproved id would be a dangling edge asserting proof of
// something no doc promises, which is the false claim this tool exists to detect.
import { describe, it, expect, beforeAll, afterAll } from "vitest";
import { mkdtemp, mkdir, readFile, writeFile, rm, cp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { buildGraph } from "./discover";
import { contextPack } from "./agentContext";
import { loadConfig, type Config } from "./config";
import { pruneBaseline, ungovernedPaths, writeBaseline } from "./ungovernedBaseline";
import type { GitRunner } from "./gitDates";
import type { Graph } from "./types";

/**
 * The frozen baseline of already-ungoverned paths (founding design §10.3): "existing untouched code
 * stays legal; new ungoverned code fails the build."
 *
 * Tested against the one-repo fixture, whose governance is deliberately mixed — `src/checkout.ts` is
 * governed by a doc's `governs:`, `src/checkout.test.ts` only by a feature's path glob, and the rest
 * of the tree by nothing at all.
 */
const FIXTURES = join(__dirname, "..", "fixtures");
const PINNED = "2000-01-01T00:00:00.000Z";
const NO_GIT: GitRunner = async () => null;

let graph: Graph;
let config: Config;

beforeAll(async () => {
  config = await loadConfig(join(FIXTURES, "one-repo"));
  graph = await buildGraph(join(FIXTURES, "one-repo"), PINNED, config, NO_GIT);
});

describe("ungovernedPaths — what the baseline is allowed to excuse", () => {
  const paths = ["src/checkout.ts", "src/checkout.test.ts", "e2e/orphan.spec.ts", "CLAUDE.md"];

  it("omits a path a doc governs", () => {
    expect(ungovernedPaths(graph, config, paths)).not.toContain("src/checkout.ts");
  });

  // The SECOND route to ownership. A generator that only consulted `governs:` edges would excuse
  // every unit test in the project, and the gate would then never engage on the code they cover.
  it("omits a path claimed only by a feature's glob", () => {
    expect(ungovernedPaths(graph, config, paths)).not.toContain("src/checkout.test.ts");
  });

  it("keeps the paths nothing governs", () => {
    const out = ungovernedPaths(graph, config, paths);
    expect(out).toContain("e2e/orphan.spec.ts");
    expect(out).toContain("CLAUDE.md");
  });

  it("is sorted and deduped, so a re-run writes identical bytes", () => {
    const out = ungovernedPaths(graph, config, ["b.ts", "a.ts", "b.ts"]);
    expect(out).toEqual(["a.ts", "b.ts"]);
  });
});

describe("pruneBaseline — the ratchet only ever turns one way", () => {
  it("drops a path that has since become governed", () => {
    expect(pruneBaseline(["a.ts", "b.ts"], ["a.ts"])).toEqual(["a.ts"]);
  });

  // The move this project never makes: a newly-written ungoverned file must NOT be able to enter an
  // existing baseline, or the gate can always be cleared by re-running the generator.
  it("refuses to admit a path the frozen baseline never had", () => {
    expect(pruneBaseline(["a.ts"], ["a.ts", "brand-new.ts"])).toEqual(["a.ts"]);
  });
});

describe("writeBaseline — the artifact the briefing hook actually reads", () => {
  let root: string;
  beforeAll(async () => {
    root = await mkdtemp(join(tmpdir(), "kg-baseline-"));
    await cp(join(FIXTURES, "one-repo"), root, { recursive: true });
  });
  afterAll(async () => { await rm(root, { recursive: true, force: true }); });

  const baselineFile = () => join(root, config.artifactDir, "ungoverned-baseline.json");

  it("writes a top-level JSON ARRAY", async () => {
    await writeBaseline({ repoRoot: root, config, graph, mode: "create" });
    const parsed = JSON.parse(await readFile(baselineFile(), "utf8"));
    // agentContextCli treats a NON-array as *absent*, and absent means "never halt". An object
    // wrapper here would look like a successful init while silently disabling the gate forever.
    expect(Array.isArray(parsed)).toBe(true);
    expect(parsed).toContain("e2e/orphan.spec.ts");
    expect(parsed).not.toContain("src/checkout.ts");
  });

  // The round trip is the real claim: what was written must grandfather what already existed while
  // still halting on something new.
  it("grandfathers what it recorded, and still halts on a path written afterwards", async () => {
    const baseline = JSON.parse(await readFile(baselineFile(), "utf8")) as string[];
    const known = contextPack(graph, config, "e2e/orphan.spec.ts", baseline);
    expect(known.halt).toBe(false);
    expect(known.grandfathered).toBe(true);
    const fresh = contextPack(graph, config, "src/newly-written.ts", baseline);
    expect(fresh.halt).toBe(true);
  });

  it("refuses to overwrite a frozen baseline, leaving it byte-identical", async () => {
    const before = await readFile(baselineFile(), "utf8");
    await writeFile(join(root, "src", "sneaked-in.ts"), "export const x = 1;\n");
    await expect(writeBaseline({ repoRoot: root, config, graph, mode: "create" })).rejects.toThrow(/frozen/i);
    expect(await readFile(baselineFile(), "utf8")).toBe(before);
  });

  it("prune keeps the count falling and never admits the new file", async () => {
    const result = await writeBaseline({ repoRoot: root, config, graph, mode: "prune" });
    expect(result.paths).not.toContain("src/sneaked-in.ts");
    const parsed = JSON.parse(await readFile(baselineFile(), "utf8")) as string[];
    expect(parsed).not.toContain("src/sneaked-in.ts");
    expect(parsed).toContain("e2e/orphan.spec.ts");
  });

  // Found by running kg-init against a foreign repo: the freeze swept the tool's OWN artifact dir
  // into the baseline — knowledge-graph.json, viewer.html, report.md, the digest. Those are
  // regenerated every build, can never be governed, and would pad the baseline with churn that makes
  // the real count meaningless.
  it("never freezes the tool's own generated artifacts", async () => {
    const fresh = await mkdtemp(join(tmpdir(), "kg-baseline-artifacts-"));
    await cp(join(FIXTURES, "one-repo"), fresh, { recursive: true });
    await mkdir(join(fresh, config.artifactDir, "digest"), { recursive: true });
    await writeFile(join(fresh, config.artifactDir, "knowledge-graph.json"), "{}");
    await writeFile(join(fresh, config.artifactDir, "viewer.html"), "<html></html>");
    await writeFile(join(fresh, config.artifactDir, "digest", "index.md"), "# digest");
    const { paths } = await writeBaseline({ repoRoot: fresh, config, graph, mode: "create" });
    expect(paths.filter((p) => p.startsWith(config.artifactDir + "/"))).toEqual([]);
    // and it still froze the real source, so the exclusion is not just an empty result
    expect(paths).toContain("e2e/orphan.spec.ts");
    await rm(fresh, { recursive: true, force: true });
  });

  // Pruning what was never frozen would intersect against an empty set and write `[]` — "nothing is
  // excused" — turning a mistyped flag into a repo-wide halt.
  it("refuses to prune a project that has no frozen baseline", async () => {
    const virgin = await mkdtemp(join(tmpdir(), "kg-baseline-virgin-"));
    await cp(join(FIXTURES, "one-repo"), virgin, { recursive: true });
    await expect(writeBaseline({ repoRoot: virgin, config, graph, mode: "prune" })).rejects.toThrow(/no .*baseline/i);
    await rm(virgin, { recursive: true, force: true });
  });

  // An enumeration that silently found nothing would write `[]` — "nothing is excused" — and halt
  // the user out of every file in their own repo. Refusing costs one error message.
  it("throws rather than freezing an empty baseline when nothing was scanned", async () => {
    const empty = await mkdtemp(join(tmpdir(), "kg-baseline-empty-"));
    await mkdir(join(empty, config.artifactDir), { recursive: true });
    await expect(writeBaseline({ repoRoot: empty, config, graph, mode: "create" })).rejects.toThrow(/no files/i);
    await rm(empty, { recursive: true, force: true });
  });
});

// covers: REQ-KG-02
import { describe, it, expect } from "vitest";
import { detectUntrackedE2e } from "./untrackedE2e";
import type { Graph, GraphNode, GraphEdge } from "./types";

/** Minimal fixture: assemble a Graph from raw nodes/edges. */
const graph = (nodes: GraphNode[], edges: GraphEdge[]): Graph => ({
  generatedAt: "2026-07-03T00:00:00Z",
  nodes,
  edges,
  issues: [],
});

const testNode = (id: string, spec: string): GraphNode => ({
  id,
  type: "test",
  title: id,
  kind: "e2e",
  spec,
});

describe("detectUntrackedE2e", () => {
  it("returns nothing when every spec has a case entry with at least one link", () => {
    const g = graph(
      [testNode("BIL-1", "billing-cascade.spec.ts")],
      [{ from: "BIL-1", to: "billing-freeze", type: "verifies", source: "x" }],
    );
    expect(detectUntrackedE2e(["e2e/billing-cascade.spec.ts"], g)).toEqual([]);
  });

  it("flags a spec file with no matching case entry at all", () => {
    const g = graph([], []);
    const issues = detectUntrackedE2e(["e2e/orphan.spec.ts"], g);
    expect(issues).toHaveLength(1);
    expect(issues[0]).toMatchObject({
      kind: "untracked-e2e",
      detail: expect.stringContaining("orphan.spec.ts"),
    });
  });

  it("flags a case entry that exists but carries no verifies/covers/features", () => {
    // A bare test node — a case entry with only id/title/spec, no links.
    const g = graph([testNode("BARE-1", "bare.spec.ts")], []);
    const issues = detectUntrackedE2e(["e2e/bare.spec.ts"], g);
    expect(issues).toHaveLength(1);
    expect(issues[0]).toMatchObject({
      kind: "untracked-e2e",
      detail: expect.stringContaining("case entry exists but has no verifies/covers/features link"),
    });
  });

  it("accepts any of verifies, covers, or tags as a qualifying link", () => {
    const g1 = graph([testNode("T-1", "s1.spec.ts")], [{ from: "T-1", to: "REQ-X", type: "covers", source: "x" }]);
    const g2 = graph([testNode("T-2", "s2.spec.ts")], [{ from: "T-2", to: "add.mapping", type: "tags", source: "x" }]);
    expect(detectUntrackedE2e(["e2e/s1.spec.ts"], g1)).toEqual([]);
    expect(detectUntrackedE2e(["e2e/s2.spec.ts"], g2)).toEqual([]);
  });

  it("ignores non-test nodes and unit tests entirely", () => {
    const unit: GraphNode = { id: "u1", type: "test", title: "u", kind: "unit-fe" };
    const g = graph([unit], []);
    // No e2e nodes → any e2e spec file should show as untracked.
    expect(detectUntrackedE2e(["e2e/x.spec.ts"], g)).toHaveLength(1);
  });

  it("matches spec paths regardless of directory prefix (case entry `spec:` is a bare filename)", () => {
    // Case entries record `spec: billing-cascade.spec.ts` (bare), while the
    // discovered file list gives us the full relative path.
    const g = graph(
      [testNode("BIL-1", "billing-cascade.spec.ts")],
      [{ from: "BIL-1", to: "d", type: "verifies", source: "x" }],
    );
    expect(detectUntrackedE2e(["svc_frontend/e2e/billing-cascade.spec.ts"], g)).toEqual([]);
  });
});

// covers: REQ-KG-VIEW-01
import { describe, it, expect } from "vitest";
import { renderViewer } from "./viewer";

const TEMPLATE = `<html><script>var KG=/*__KG_DATA__*/{nodes:[],edges:[],issues:[]}/*__KG_END__*/;</script></html>`;
const GRAPH = { generatedAt: "T", nodes: [{ id: "backend:x", type: "doc", title: "X" }], edges: [], issues: [] } as any;

describe("renderViewer", () => {
  it("inlines the graph JSON at the marker", () => {
    const out = renderViewer(GRAPH, TEMPLATE);
    expect(out).toContain('"backend:x"');
    expect(out).not.toContain("/*__KG_DATA__*/");
  });
  it("is deterministic for the same graph", () => {
    expect(renderViewer(GRAPH, TEMPLATE)).toBe(renderViewer(GRAPH, TEMPLATE));
  });
  it("throws if the marker is missing", () => {
    expect(() => renderViewer(GRAPH, "<html>no marker</html>")).toThrow();
  });
  it("produces a parseable KG object (no double-object / invalid JS)", () => {
    const out = renderViewer(GRAPH, TEMPLATE);
    const m = out.match(/var KG=(\{[\s\S]*\});/);
    expect(m).not.toBeNull();
    const kg = JSON.parse(m![1]);
    expect(kg.nodes[0].id).toBe("backend:x");
  });
});

const tpl = 'var KG=/*__KG_DATA__*/{}/*__KG_END__*/;\nvar DELTA=/*__KG_DELTA__*/null/*__KG_END_DELTA__*/;';
const g = { generatedAt: "T", nodes: [], edges: [], issues: [] } as any;

it("injects the delta between DELTA markers", () => {
